SpriteFacingAndAnimationTable:
; This table is used for overworld sprites $1-$9.
dw .StandingDown, .NormalOAM ; facing down, walk animation frame 0
dw .WalkingDown, .NormalOAM ; facing down, walk animation frame 1
dw .StandingDown, .NormalOAM ; facing down, walk animation frame 2
dw .WalkingDown, .FlippedOAM ; facing down, walk animation frame 3
dw .StandingUp, .NormalOAM ; facing up, walk animation frame 0
dw .WalkingUp, .NormalOAM ; facing up, walk animation frame 1
dw .StandingUp, .NormalOAM ; facing up, walk animation frame 2
dw .WalkingUp, .FlippedOAM ; facing up, walk animation frame 3
dw .StandingLeft, .NormalOAM ; facing left, walk animation frame 0
dw .WalkingLeft, .NormalOAM ; facing left, walk animation frame 1
dw .StandingLeft, .NormalOAM ; facing left, walk animation frame 2
dw .WalkingLeft, .NormalOAM ; facing left, walk animation frame 3
dw .StandingLeft, .FlippedOAM ; facing right, walk animation frame 0
dw .WalkingLeft, .FlippedOAM ; facing right, walk animation frame 1
dw .StandingLeft, .FlippedOAM ; facing right, walk animation frame 2
dw .WalkingLeft, .FlippedOAM ; facing right, walk animation frame 3
; The rest of this table is used for sprites $a and $b.
; All orientation and animation parameters lead to the same result.
; Used for immobile sprites like items on the ground.
dw .StandingDown, .NormalOAM ; facing down, walk animation frame 0
dw .StandingDown, .NormalOAM ; facing down, walk animation frame 1
dw .StandingDown, .NormalOAM ; facing down, walk animation frame 2
dw .StandingDown, .NormalOAM ; facing down, walk animation frame 3
dw .StandingDown, .NormalOAM ; facing up, walk animation frame 0
dw .StandingDown, .NormalOAM ; facing up, walk animation frame 1
dw .StandingDown, .NormalOAM ; facing up, walk animation frame 2
dw .StandingDown, .NormalOAM ; facing up, walk animation frame 3
dw .StandingDown, .NormalOAM ; facing left, walk animation frame 0
dw .StandingDown, .NormalOAM ; facing left, walk animation frame 1
dw .StandingDown, .NormalOAM ; facing left, walk animation frame 2
dw .StandingDown, .NormalOAM ; facing left, walk animation frame 3
dw .StandingDown, .NormalOAM ; facing right, walk animation frame 0
dw .StandingDown, .NormalOAM ; facing right, walk animation frame 1
dw .StandingDown, .NormalOAM ; facing right, walk animation frame 2
dw .StandingDown, .NormalOAM ; facing right, walk animation frame 3
; four tile ids compose an overworld sprite
.StandingDown: db $00, $01, $02, $03
.WalkingDown: db $80, $81, $82, $83
.StandingUp: db $04, $05, $06, $07
.WalkingUp: db $84, $85, $86, $87
.StandingLeft: db $08, $09, $0a, $0b
.WalkingLeft: db $88, $89, $8a, $8b
.NormalOAM:
; y, x, attributes
db 0, 0, $00 ; top left
db 0, 8, $00 ; top right
db 8, 0, UNDER_GRASS ; bottom left
db 8, 8, UNDER_GRASS | FACING_END ; bottom right
.FlippedOAM:
; y, x, attributes
db 0, 8, OAM_XFLIP ; top left
db 0, 0, OAM_XFLIP ; top right
db 8, 8, OAM_XFLIP | UNDER_GRASS ; bottom left
db 8, 0, OAM_XFLIP | UNDER_GRASS | FACING_END ; bottom right
; END_INCLUDE \\?\M:\Code\Research\pokered-master\data\sprites\facings.asm
; BEGIN_INCLUDE \\?\M:\Code\Research\pokered-master\engine\events\black_out.asm
ResetStatusAndHalveMoneyOnBlackout::
; Reset player status on blackout.
xor a
ld [wBattleResult], a
ld [wWalkBikeSurfState], a
ld [wIsInBattle], a
ld [wMapPalOffset], a
ld [wNPCMovementScriptFunctionNum], a
ldh [hJoyHeld], a
ld [wNPCMovementScriptPointerTableNum], a
ld [wMiscFlags], a
ldh [hMoney], a
ldh [hMoney + 1], a
ldh [hMoney + 2], a
call HasEnoughMoney
jr c, .lostmoney ; never happens
; Halve the player's money.
ld a, [wPlayerMoney]
ldh [hMoney], a
ld a, [wPlayerMoney + 1]
ldh [hMoney + 1], a
ld a, [wPlayerMoney + 2]
ldh [hMoney + 2], a
xor a
ldh [hDivideBCDDivisor], a
ldh [hDivideBCDDivisor + 1], a
ld a, 2
ldh [hDivideBCDDivisor + 2], a
predef DivideBCDPredef3
ldh a, [hDivideBCDQuotient]
ld [wPlayerMoney], a
ldh a, [hDivideBCDQuotient + 1]
ld [wPlayerMoney + 1], a
ldh a, [hDivideBCDQuotient + 2]
ld [wPlayerMoney + 2], a
.lostmoney
ld hl, wStatusFlags6
set BIT_FLY_OR_DUNGEON_WARP, [hl]
res BIT_FLY_WARP, [hl]
set BIT_ESCAPE_WARP, [hl]
ld a, PAD_BUTTONS | PAD_CTRL_PAD
ld [wJoyIgnore], a
predef_jump HealParty
; END_INCLUDE \\?\M:\Code\Research\pokered-master\engine\events\black_out.asm
; BEGIN_INCLUDE \\?\M:\Code\Research\pokered-master\data\pokemon\mew.asm
; Mew's pics and base data are not grouped with the other Pok mon
; because it was a last-minute addition "as a kind of prank".
; Shigeki Morimoto explained in an Iwata Asks interview:
; "We put Mew in right at the very end. The cartridge was really full and
; there wasn't room for much more on there. Then the debug features which
; weren't going to be included in the final version of the game were removed,
; creating a miniscule 300 bytes of free space. So we thought that we could
; slot Mew in there. What we did would be unthinkable nowadays!"
; https://iwataasks.nintendo.com/interviews/ds/pokemon/0/0/
MewPicFront:: INCBIN "gfx/pokemon/front/mew.pic"
MewPicBack:: INCBIN "gfx/pokemon/back/mewb.pic"
MewBaseStats::
INCLUDE "data/pokemon/base_stats/mew.asm"
; END_INCLUDE \\?\M:\Code\Research\pokered-master\data\pokemon\mew.asm
; BEGIN_INCLUDE \\?\M:\Code\Research\pokered-master\engine\battle\safari_zone.asm
PrintSafariZoneBattleText:
ld hl, wSafariBaitFactor
ld a, [hl]
and a
jr z, .no_bait
dec [hl]
ld hl, SafariZoneEatingText
jr .done
.no_bait
dec hl
ld a, [hl]
and a
ret z
dec [hl]
ld hl, SafariZoneAngryText
jr nz, .done
push hl
ld a, [wEnemyMonSpecies]
ld [wCurSpecies], a
call GetMonHeader
ld a, [wMonHCatchRate]
ld [wEnemyMonActualCatchRate], a
pop hl
.done
push hl
call LoadScreenTilesFromBuffer1
pop hl
jp PrintText
SafariZoneEatingText:
text_far _SafariZoneEatingText
text_end
SafariZoneAngryText:
text_far _SafariZoneAngryText
text_end
; END_INCLUDE \\?\M:\Code\Research\pokered-master\engine\battle\safari_zone.asm
; BEGIN_INCLUDE \\?\M:\Code\Research\pokered-master\engine\movie\title.asm
CopyDebugName:
ld bc, NAME_LENGTH
jp CopyData
PrepareTitleScreen::
; These debug names are already copied later in PrepareOakSpeech.
; Removing the unused copies below has no apparent impact.
; CopyDebugName can also be safely deleted afterwards.
ld hl, DebugNewGamePlayerName
ld de, wPlayerName
call CopyDebugName
ld hl, DebugNewGameRivalName
ld de, wRivalName
call CopyDebugName
xor a
ldh [hWY], a
ld [wLetterPrintingDelayFlags], a
ld hl, wStatusFlags6
ld [hli], a
ASSERT wStatusFlags6 + 1 == wStatusFlags7
ld [hli], a
ASSERT wStatusFlags7 + 1 == wElite4Flags
ld [hl], a
ld a, BANK(Music_TitleScreen)
ld [wAudioROMBank], a
ld [wAudioSavedROMBank], a
DisplayTitleScreen:
call GBPalWhiteOut
ld a, $1
ldh [hAutoBGTransferEnabled], a
xor a
ldh [hTileAnimations], a
ldh [hSCX], a
ld a, $40
ldh [hSCY], a
ld a, $90
ldh [hWY], a
call ClearScreen
call DisableLCD
call LoadFontTilePatterns
ld hl, NintendoCopyrightLogoGraphics
ld de, vTitleLogo2 tile 16
ld bc, 5 tiles
ld a, BANK(NintendoCopyrightLogoGraphics)
call FarCopyData2
ld hl, GameFreakLogoGraphics
ld de, vTitleLogo2 tile (16 + 5)
ld bc, 9 tiles
ld a, BANK(GameFreakLogoGraphics)
call FarCopyData2
ld hl, PokemonLogoGraphics
ld de, vTitleLogo
ld bc, $60 tiles
ld a, BANK(PokemonLogoGraphics)
call FarCopyData2 ; first chunk
ld hl, PokemonLogoGraphics tile $60
ld de, vTitleLogo2
ld bc, $10 tiles
ld a, BANK(PokemonLogoGraphics)
call FarCopyData2 ; second chunk
ld hl, Version_GFX
ld de, vChars2 tile $60 + (10 tiles - (Version_GFXEnd - Version_GFX) * 2) / 2
ld bc, Version_GFXEnd - Version_GFX
ld a, BANK(Version_GFX)
call FarCopyDataDouble
call ClearBothBGMaps
; place tiles for pokemon logo (except for the last row)
hlcoord 2, 1
ld a, $80
ld de, SCREEN_WIDTH
ld c, 6
.pokemonLogoTileLoop
ld b, $10
push hl
.pokemonLogoTileRowLoop ; place tiles for one row
ld [hli], a
inc a
dec b
jr nz, .pokemonLogoTileRowLoop
pop hl
add hl, de
dec c
jr nz, .pokemonLogoTileLoop
; place tiles for the last row of the pokemon logo
hlcoord 2, 7
ld a, $31
ld b, $10
.pokemonLogoLastTileRowLoop
ld [hli], a
inc a
dec b
jr nz, .pokemonLogoLastTileRowLoop
call DrawPlayerCharacter
; put a pokeball in the player's hand
ld hl, wShadowOAMSprite10
ld a, $74
ld [hl], a
; place tiles for title screen copyright
hlcoord 2, 17
ld de, .tileScreenCopyrightTiles
ld b, .tileScreenCopyrightTilesEnd - .tileScreenCopyrightTiles
.tileScreenCopyrightTilesLoop
ld a, [de]
ld [hli], a
inc de
dec b
jr nz, .tileScreenCopyrightTilesLoop
jr .next
.tileScreenCopyrightTiles
db $41,$42,$43,$42,$44,$42,$45,$46,$47,$48,$49,$4A,$4B,$4C,$4D,$4E ; '95.'96.'98 GAME FREAK inc.
.tileScreenCopyrightTilesEnd
.next
call SaveScreenTilesToBuffer2
call LoadScreenTilesFromBuffer2
call EnableLCD
IF DEF(_RED)
ld a, STARTER1 ; which Pokemon to show first on the title screen
ENDC
IF DEF(_BLUE)
ld a, STARTER2 ; which Pokemon to show first on the title screen
ENDC
ld [wTitleMonSpecies], a
call LoadTitleMonSprite
ld a, HIGH(vBGMap0 + $300)
call TitleScreenCopyTileMapToVRAM
call SaveScreenTilesToBuffer1
ld a, $40
ldh [hWY], a
call LoadScreenTilesFromBuffer2
ld a, HIGH(vBGMap0)
call TitleScreenCopyTileMapToVRAM
ld b, SET_PAL_TITLE_SCREEN
call RunPaletteCommand
call GBPalNormal
ld a, %11100100
ldh [rOBP0], a
; make pokemon logo bounce up and down
ld bc, hSCY ; background scroll Y
ld hl, .TitleScreenPokemonLogoYScrolls
.bouncePokemonLogoLoop
ld a, [hli]
and a
jr z, .finishedBouncingPokemonLogo
ld d, a
cp -3
jr nz, .skipPlayingSound
ld a, SFX_INTRO_CRASH
call PlaySound
.skipPlayingSound
ld a, [hli]
ld e, a
call .ScrollTitleScreenPokemonLogo
jr .bouncePokemonLogoLoop
.TitleScreenPokemonLogoYScrolls:
; Controls the bouncing effect of the Pokemon logo on the title screen
db -4,16 ; y scroll amount, number of times to scroll
db 3,4
db -3,4
db 2,2
db -2,2
db 1,2
db -1,2
db 0 ; terminate list with 0
.ScrollTitleScreenPokemonLogo:
; Scrolls the Pokemon logo on the title screen to create the bouncing effect
; Scrolls d pixels e times
call DelayFrame
ld a, [bc] ; background scroll Y
add d
ld [bc], a
dec e
jr nz, .ScrollTitleScreenPokemonLogo
ret
.finishedBouncingPokemonLogo
call LoadScreenTilesFromBuffer1
ld c, 36
call DelayFrames
ld a, SFX_INTRO_WHOOSH
call PlaySound
; scroll game version in from the right
call PrintGameVersionOnTitleScreen
ld a, SCREEN_HEIGHT_PX
ldh [hWY], a
ld d, 144
.scrollTitleScreenGameVersionLoop
ld h, d
ld l, 64
call ScrollTitleScreenGameVersion
ld h, 0
ld l, 80
call ScrollTitleScreenGameVersion
ld a, d
add 4
ld d, a
and a
jr nz, .scrollTitleScreenGameVersionLoop
ld a, HIGH(vBGMap1)
call TitleScreenCopyTileMapToVRAM
call LoadScreenTilesFromBuffer2
call PrintGameVersionOnTitleScreen
call Delay3
call WaitForSoundToFinish
ld a, MUSIC_TITLE_SCREEN
ld [wNewSoundID], a
call PlaySound
xor a
ld [wUnusedFlag], a
; Keep scrolling in new mons indefinitely until the user performs input.
.awaitUserInterruptionLoop
ld c, 200
call CheckForUserInterruption
jr c, .finishedWaiting
call TitleScreenScrollInMon
ld c, 1
call CheckForUserInterruption
jr c, .finishedWaiting
farcall TitleScreenAnimateBallIfStarterOut
call TitleScreenPickNewMon
jr .awaitUserInterruptionLoop
.finishedWaiting
ld a, [wTitleMonSpecies]
call PlayCry
call WaitForSoundToFinish
call GBPalWhiteOutWithDelay3
call ClearSprites
xor a
ldh [hWY], a
inc a
ldh [hAutoBGTransferEnabled], a
call ClearScreen
ld a, HIGH(vBGMap0)
call TitleScreenCopyTileMapToVRAM
ld a, HIGH(vBGMap1)
call TitleScreenCopyTileMapToVRAM
call Delay3
call LoadGBPal
ldh a, [hJoyHeld]
ld b, a
and PAD_UP | PAD_SELECT | PAD_B
cp PAD_UP | PAD_SELECT | PAD_B
jp z, .doClearSaveDialogue
IF DEF(_DEBUG)
ld a, b
bit B_PAD_SELECT, a
jp nz, DebugMenu
ENDC
jp MainMenu
.doClearSaveDialogue
farjp DoClearSaveDialogue
TitleScreenPickNewMon:
ld a, HIGH(vBGMap0)
call TitleScreenCopyTileMapToVRAM
.loop
; Keep looping until a mon different from the current one is picked.
call Random
and $f
ld c, a
ld b, 0
ld hl, TitleMons
add hl, bc
ld a, [hl]
ld hl, wTitleMonSpecies
; Can't be the same as before.
cp [hl]
jr z, .loop
ld [hl], a
call LoadTitleMonSprite
ld a, $90
ldh [hWY], a
ld d, 1 ; scroll out
farcall TitleScroll
ret
TitleScreenScrollInMon:
ld d, 0 ; scroll in
farcall TitleScroll
xor a
ldh [hWY], a
ret
ScrollTitleScreenGameVersion:
.wait
ldh a, [rLY]
cp l
jr nz, .wait
ld a, h
ldh [rSCX], a
.wait2
ldh a, [rLY]
cp h
jr z, .wait2
ret
DrawPlayerCharacter:
ld hl, PlayerCharacterTitleGraphics
ld de, vSprites
ld bc, PlayerCharacterTitleGraphicsEnd - PlayerCharacterTitleGraphics
ld a, BANK(PlayerCharacterTitleGraphics)
call FarCopyData2
call ClearSprites
xor a
ld [wPlayerCharacterOAMTile], a
ld hl, wShadowOAM
lb de, $60, $5a
ld b, 7
.loop
push de
ld c, 5
.innerLoop
ld a, d
ld [hli], a ; Y
ld a, e
ld [hli], a ; X
add 8
ld e, a
ld a, [wPlayerCharacterOAMTile]
ld [hli], a ; tile
inc a
ld [wPlayerCharacterOAMTile], a
inc hl
dec c
jr nz, .innerLoop
pop de
ld a, 8
add d
ld d, a
dec b
jr nz, .loop
ret
ClearBothBGMaps:
ld hl, vBGMap0
ld bc, 2 * TILEMAP_AREA
ld a, ' '
jp FillMemory
LoadTitleMonSprite:
ld [wCurPartySpecies], a
ld [wCurSpecies], a
hlcoord 5, 10
call GetMonHeader
jp LoadFrontSpriteByMonIndex
TitleScreenCopyTileMapToVRAM:
ldh [hAutoBGTransferDest + 1], a
jp Delay3
LoadCopyrightAndTextBoxTiles:
xor a
ldh [hWY], a
call ClearScreen
call LoadTextBoxTilePatterns
LoadCopyrightTiles:
ld de, NintendoCopyrightLogoGraphics
ld hl, vChars2 tile $60
lb bc, BANK(NintendoCopyrightLogoGraphics), (GameFreakLogoGraphicsEnd - NintendoCopyrightLogoGraphics) / TILE_SIZE
call CopyVideoData
hlcoord 2, 7
ld de, CopyrightTextString
jp PlaceString
CopyrightTextString:
db $60,$61,$62,$61,$63,$61,$64,$7F,$65,$66,$67,$68,$69,$6A ; '95.'96.'98 Nintendo
next $60,$61,$62,$61,$63,$61,$64,$7F,$6B,$6C,$6D,$6E,$6F,$70,$71,$72 ; '95.'96.'98 Creatures inc.
next $60,$61,$62,$61,$63,$61,$64,$7F,$73,$74,$75,$76,$77,$78,$79,$7A,$7B ; '95.'96.'98 GAME FREAK inc.
db "@"
INCLUDE "data/pokemon/title_mons.asm"
; prints version text (red, blue)
PrintGameVersionOnTitleScreen:
hlcoord 7, 8
ld de, VersionOnTitleScreenText
jp PlaceString
; these point to special tiles specifically loaded for that purpose and are not usual text
VersionOnTitleScreenText:
IF DEF(_RED)
db $60,$61,$7F,$65,$66,$67,$68,$69,"@" ; "Red Version"
ENDC
IF DEF(_BLUE)
db $61,$62,$63,$64,$65,$66,$67,$68,"@" ; "Blue Version"
ENDC
DebugNewGamePlayerName:
db "NINTEN@"
DebugNewGameRivalName:
db "SONY@"
