call z, DelayFrames ; delay if using internal clock
ld a, [wLinkState]
cp LINK_STATE_START_BATTLE
ld a, LINK_STATE_TRADING
ld [wLinkState], a
jr nz, .trading
ld a, LINK_STATE_BATTLING
ld [wLinkState], a
ld a, OPP_RIVAL1
ld [wCurOpponent], a
call ClearScreen
call Delay3
ld hl, wOptions
res BIT_BATTLE_ANIMATION, [hl]
predef InitOpponent
predef HealParty
jp ReturnToCableClubRoom
.trading
