LearnMove:
call SaveScreenTilesToBuffer1
ld a, [wWhichPokemon]
ld hl, wPartyMonNicks
call GetPartyMonName
ld hl, wNameBuffer
ld de, wLearnMoveMonName
ld bc, NAME_LENGTH
