_Joypad::
; hJoyReleased: (hJoyLast ^ hJoyInput) & hJoyLast
; hJoyPressed: (hJoyLast ^ hJoyInput) & hJoyInput
ldh a, [hJoyInput]
cp PAD_BUTTONS ; soft reset
jp z, TrySoftReset
ld b, a
ldh a, [hJoyLast]
ld e, a
xor b
ld d, a
and e
ldh [hJoyReleased], a
ld a, d
and b
ldh [hJoyPressed], a
ld a, b
ldh [hJoyLast], a
ld a, [wStatusFlags5]
bit BIT_DISABLE_JOYPAD, a
jr nz, DiscardButtonPresses
ldh a, [hJoyLast]
ldh [hJoyHeld], a
ld a, [wJoyIgnore]
and a
ret z
cpl
ld b, a
ldh a, [hJoyHeld]
and b
ldh [hJoyHeld], a
ldh a, [hJoyPressed]
and b
ldh [hJoyPressed], a
ret
DiscardButtonPresses:
xor a
ldh [hJoyHeld], a
ldh [hJoyPressed], a
ldh [hJoyReleased], a
ret
TrySoftReset:
call DelayFrame
; deselect (redundant)
ld a, $30
ldh [rJOYP], a
ld hl, hSoftReset
dec [hl]
jp z, SoftReset
jp Joypad
; END_INCLUDE \\?\M:\Code\Research\pokered-master\engine\joypad.asm
