dw ItemUsePPRestore ; ETHER
dw ItemUsePPRestore ; MAX_ETHER
dw ItemUsePPRestore ; ELIXER
dw ItemUsePPRestore ; MAX_ELIXER
ItemUseBall:
; Balls can't be used out of battle.
ld a, [wIsInBattle]
and a
jp z, ItemUseNotTime
; Balls can't catch trainers' Pok mon.
dec a
jp nz, ThrowBallAtTrainerMon
; If this is for the old man battle, skip checking if the party & box are full.
ld a, [wBattleType]
dec a
jr z, .canUseBall
ld a, [wPartyCount] ; is party full?
cp PARTY_LENGTH
jr nz, .canUseBall
ld a, [wBoxCount] ; is box full?
cp MONS_PER_BOX
jp z, BoxFullCannotThrowBall
.canUseBall
xor a
ld [wCapturedMonSpecies], a
ld a, [wBattleType]
cp BATTLE_TYPE_SAFARI
jr nz, .skipSafariZoneCode
.safariZone
ld hl, wNumSafariBalls
dec [hl] ; remove a Safari Ball
.skipSafariZoneCode
call RunDefaultPaletteCommand
ld a, $43 ; successful capture value
ld [wPokeBallAnimData], a
call LoadScreenTilesFromBuffer1
ld hl, ItemUseText00
call PrintText
; If the player is fighting an unidentified ghost, set the value that indicates
; the Pok mon can't be caught and skip the capture calculations.
callfar IsGhostBattle
ld b, $10 ; can't be caught value
jp z, .setAnimData
ld a, [wBattleType]
dec a
jr nz, .notOldManBattle
; Old Man battle
ld hl, wGrassRate
ld de, wPlayerName
ld bc, NAME_LENGTH
call CopyData ; save the player's name in the Wild Monster data (part of the Cinnabar Island Missingno. glitch)
jp .captured
.notOldManBattle
; If the player is fighting the ghost Marowak, set the value that indicates the
; Pok mon can't be caught and skip the capture calculations.
ld a, [wCurMap]
cp POKEMON_TOWER_6F
jr nz, .loop
ld a, [wEnemyMonSpecies2]
cp RESTLESS_SOUL
ld b, $10 ; can't be caught value
jp z, .setAnimData
; Get the first random number. Let it be called Rand1.
; Rand1 must be within a certain range according the kind of ball being thrown.
; The ranges are as follows.
; Pok Ball: [0, 255]
; Great Ball: [0, 200]
; Ultra/Safari Ball: [0, 150]
; Loop until an acceptable number is found.
.loop
call Random
ld b, a
; Get the item ID.
ld hl, wCurItem
ld a, [hl]
; The Master Ball always succeeds.
cp MASTER_BALL
jp z, .captured
; Anything will do for the basic Pok Ball.
cp POKE_BALL
jr z, .checkForAilments
; If it's a Great/Ultra/Safari Ball and Rand1 is greater than 200, try again.
ld a, 200
cp b
jr c, .loop
; Less than or equal to 200 is good enough for a Great Ball.
ld a, [hl]
cp GREAT_BALL
jr z, .checkForAilments
; If it's an Ultra/Safari Ball and Rand1 is greater than 150, try again.
ld a, 150
cp b
jr c, .loop
.checkForAilments
; Pok mon can be caught more easily with a status ailment.
; Depending on the status ailment, a certain value will be subtracted from
; Rand1. Let this value be called Status.
; The larger Status is, the more easily the Pok mon can be caught.
; no status ailment: Status = 0
; Burn/Paralysis/Poison: Status = 12
; Freeze/Sleep: Status = 25
; If Status is greater than Rand1, the Pok mon will be caught for sure.
ld a, [wEnemyMonStatus]
and a
jr z, .skipAilmentValueSubtraction ; no ailments
and (1 << FRZ) | SLP_MASK
ld c, 12
jr z, .notFrozenOrAsleep
ld c, 25
.notFrozenOrAsleep
ld a, b
sub c
jp c, .captured
ld b, a
.skipAilmentValueSubtraction
push bc ; save (Rand1 - Status)
; Calculate MaxHP * 255.
xor a
ldh [hMultiplicand], a
ld hl, wEnemyMonMaxHP
ld a, [hli]
ldh [hMultiplicand + 1], a
ld a, [hl]
ldh [hMultiplicand + 2], a
ld a, 255
ldh [hMultiplier], a
call Multiply
; Determine BallFactor. It's 8 for Great Balls and 12 for the others.
ld a, [wCurItem]
cp GREAT_BALL
ld a, 12
jr nz, .skip1
ld a, 8
.skip1
; Note that the results of all division operations are floored.
; Calculate (MaxHP * 255) / BallFactor.
ldh [hDivisor], a
ld b, 4 ; number of bytes in dividend
call Divide
; Divide the enemy's current HP by 4. HP is not supposed to exceed 999 so
; the result should fit in a. If the division results in a quotient of 0,
; change it to 1.
ld hl, wEnemyMonHP
ld a, [hli]
ld b, a
ld a, [hl]
srl b
rr a
srl b
rr a
and a
jr nz, .skip2
inc a
.skip2
; Let W = ((MaxHP * 255) / BallFactor) / max(HP / 4, 1). Calculate W.
ldh [hDivisor], a
ld b, 4
call Divide
; If W > 255, store 255 in [hQuotient + 3].
; Let X = min(W, 255) = [hQuotient + 3].
ldh a, [hQuotient + 2]
and a
jr z, .skip3
ld a, 255
ldh [hQuotient + 3], a
.skip3
pop bc ; b = Rand1 - Status
; If Rand1 - Status > CatchRate, the ball fails to capture the Pok mon.
ld a, [wEnemyMonActualCatchRate]
cp b
jr c, .failedToCapture
; If W > 255, the ball captures the Pok mon.
ldh a, [hQuotient + 2]
and a
jr nz, .captured
call Random ; Let this random number be called Rand2.
; If Rand2 > X, the ball fails to capture the Pok mon.
ld b, a
ldh a, [hQuotient + 3]
cp b
jr c, .failedToCapture
.captured
jr .skipShakeCalculations
.failedToCapture
ldh a, [hQuotient + 3]
ld [wPokeBallCaptureCalcTemp], a ; Save X.
; Calculate CatchRate * 100.
xor a
ldh [hMultiplicand], a
ldh [hMultiplicand + 1], a
ld a, [wEnemyMonActualCatchRate]
ldh [hMultiplicand + 2], a
ld a, 100
ldh [hMultiplier], a
call Multiply
; Determine BallFactor2.
; Pok Ball: BallFactor2 = 255
; Great Ball: BallFactor2 = 200
; Ultra/Safari Ball: BallFactor2 = 150
ld a, [wCurItem]
ld b, 255
cp POKE_BALL
jr z, .skip4
ld b, 200
cp GREAT_BALL
jr z, .skip4
ld b, 150
cp ULTRA_BALL
jr z, .skip4
.skip4
; Let Y = (CatchRate * 100) / BallFactor2. Calculate Y.
ld a, b
ldh [hDivisor], a
ld b, 4
call Divide
; If Y > 255, there are 3 shakes.
; Note that this shouldn't be possible.
; The maximum value of Y is (255 * 100) / 150 = 170.
ldh a, [hQuotient + 2]
and a
ld b, $63 ; 3 shakes
jr nz, .setAnimData
; Calculate X * Y.
ld a, [wPokeBallCaptureCalcTemp]
ldh [hMultiplier], a
call Multiply
; Calculate (X * Y) / 255.
ld a, 255
ldh [hDivisor], a
ld b, 4
call Divide
; Determine Status2.
; no status ailment: Status2 = 0
; Burn/Paralysis/Poison: Status2 = 5
; Freeze/Sleep: Status2 = 10
ld a, [wEnemyMonStatus]
and a
jr z, .skip5
and (1 << FRZ) | SLP_MASK
ld b, 5
jr z, .addAilmentValue
ld b, 10
.addAilmentValue
; If the Pok mon has a status ailment, add Status2.
ldh a, [hQuotient + 3]
add b
ldh [hQuotient + 3], a
.skip5
; Finally determine the number of shakes.
; Let Z = ((X * Y) / 255) + Status2 = [hQuotient + 3].
; The number of shakes depend on the range Z is in.
; 0 Z < 10: 0 shakes (the ball misses)
; 10 Z < 30: 1 shake
; 30 Z < 70: 2 shakes
; 70 Z: 3 shakes
ldh a, [hQuotient + 3]
cp 10
ld b, $20
jr c, .setAnimData
cp 30
ld b, $61
jr c, .setAnimData
cp 70
ld b, $62
jr c, .setAnimData
ld b, $63
.setAnimData
ld a, b
ld [wPokeBallAnimData], a
.skipShakeCalculations
ld c, 20
call DelayFrames
; Do the animation.
ld a, TOSS_ANIM
ld [wAnimationID], a
xor a
ldh [hWhoseTurn], a
ld [wAnimationType], a
ld [wDamageMultipliers], a
ld a, [wWhichPokemon]
push af
ld a, [wCurItem]
push af
predef MoveAnimation
pop af
ld [wCurItem], a
pop af
ld [wWhichPokemon], a
; Determine the message to display from the animation.
ld a, [wPokeBallAnimData]
cp $10
ld hl, ItemUseBallText00
jp z, .printMessage
cp $20
ld hl, ItemUseBallText01
jp z, .printMessage
cp $61
ld hl, ItemUseBallText02
jp z, .printMessage
cp $62
ld hl, ItemUseBallText03
jp z, .printMessage
cp $63
ld hl, ItemUseBallText04
jp z, .printMessage
; Save current HP.
ld hl, wEnemyMonHP
ld a, [hli]
push af
ld a, [hli]
push af
; Save status ailment.
inc hl
ld a, [hl]
push af
push hl
; Bug: If the Pok mon is transformed, the Pok mon is assumed to be a Ditto.
; This is a bug because a wild Pok mon could have used Transform via
; Mirror Move even though the only wild Pok mon that knows Transform is Ditto.
ld hl, wEnemyBattleStatus3
bit TRANSFORMED, [hl]
jr z, .notTransformed
ld a, DITTO
ld [wEnemyMonSpecies2], a
jr .skip6
.notTransformed
; If the Pok mon is not transformed, set the transformed bit and copy the
; DVs to wTransformedEnemyMonOriginalDVs so that LoadEnemyMonData won't generate
; new DVs.
set TRANSFORMED, [hl]
ld hl, wTransformedEnemyMonOriginalDVs
ld a, [wEnemyMonDVs]
ld [hli], a
ld a, [wEnemyMonDVs + 1]
ld [hl], a
.skip6
ld a, [wCurPartySpecies]
push af
ld a, [wEnemyMonSpecies2]
ld [wCurPartySpecies], a
ld a, [wEnemyMonLevel]
ld [wCurEnemyLevel], a
callfar LoadEnemyMonData
pop af
ld [wCurPartySpecies], a
pop hl
pop af
ld [hld], a
dec hl
pop af
ld [hld], a
pop af
ld [hl], a
ld a, [wEnemyMonSpecies]
ld [wCapturedMonSpecies], a
ld [wCurPartySpecies], a
ld [wPokedexNum], a
ld a, [wBattleType]
dec a ; is this the old man battle?
jr z, .oldManCaughtMon ; if so, don't give the player the caught Pok mon
ld hl, ItemUseBallText05
call PrintText
; Add the caught Pok mon to the Pok dex.
predef IndexToPokedex
ld a, [wPokedexNum]
dec a
ld c, a
ld b, FLAG_TEST
ld hl, wPokedexOwned
predef FlagActionPredef
ld a, c
push af
ld a, [wPokedexNum]
dec a
ld c, a
ld b, FLAG_SET
predef FlagActionPredef
pop af
and a ; was the Pok mon already in the Pok dex?
jr nz, .skipShowingPokedexData ; if so, don't show the Pok dex data
ld hl, ItemUseBallText06
call PrintText
call ClearSprites
ld a, [wEnemyMonSpecies]
ld [wPokedexNum], a
predef ShowPokedexData
.skipShowingPokedexData
ld a, [wPartyCount]
cp PARTY_LENGTH ; is party full?
jr z, .sendToBox
xor a ; PLAYER_PARTY_DATA
ld [wMonDataLocation], a
call ClearSprites
call AddPartyMon
jr .done
.sendToBox
call ClearSprites
call SendNewMonToBox
ld hl, ItemUseBallText07
CheckEvent EVENT_MET_BILL
jr nz, .printTransferredToPCText
ld hl, ItemUseBallText08
.printTransferredToPCText
call PrintText
jr .done
.oldManCaughtMon
ld hl, ItemUseBallText05
.printMessage
call PrintText
call ClearSprites
.done
ld a, [wBattleType]
and a ; is this the old man battle?
ret nz ; if so, don't remove a ball from the bag
; Remove a ball from the bag.
ld hl, wNumBagItems
inc a
ld [wItemQuantity], a
jp RemoveItemFromInventory
ItemUseBallText00:
;"It dodged the thrown ball!"
;"This pokemon can't be caught"
text_far _ItemUseBallText00
text_end
ItemUseBallText01:
;"You missed the pokemon!"
text_far _ItemUseBallText01
text_end
ItemUseBallText02:
;"Darn! The pokemon broke free!"
text_far _ItemUseBallText02
text_end
ItemUseBallText03:
;"Aww! It appeared to be caught!"
text_far _ItemUseBallText03
text_end
ItemUseBallText04:
;"Shoot! It was so close too!"
text_far _ItemUseBallText04
text_end
ItemUseBallText05:
;"All right! {MonName} was caught!"
;play sound
text_far _ItemUseBallText05
sound_caught_mon
text_promptbutton
text_end
ItemUseBallText07:
;"X was transferred to Bill's PC"
text_far _ItemUseBallText07
text_end
ItemUseBallText08:
;"X was transferred to someone's PC"
text_far _ItemUseBallText08
text_end
ItemUseBallText06:
;"New DEX data will be added..."
;play sound
text_far _ItemUseBallText06
sound_dex_page_added
text_promptbutton
text_end
ItemUseTownMap:
ld a, [wIsInBattle]
and a
jp nz, ItemUseNotTime
farjp DisplayTownMap
ItemUseBicycle:
ld a, [wIsInBattle]
and a
jp nz, ItemUseNotTime
ld a, [wWalkBikeSurfState]
ld [wWalkBikeSurfStateCopy], a
cp 2 ; is the player surfing?
jp z, ItemUseNotTime
dec a ; is player already bicycling?
jr nz, .tryToGetOnBike
; get off bike
call ItemUseReloadOverworldData
xor a
ld [wWalkBikeSurfState], a ; change player state to walking
call PlayDefaultMusic ; play walking music
ld hl, GotOffBicycleText
jr .printText
.tryToGetOnBike
call IsBikeRidingAllowed
jp nc, NoCyclingAllowedHere
call ItemUseReloadOverworldData
xor a ; no keys pressed
ldh [hJoyHeld], a ; current joypad state
inc a
ld [wWalkBikeSurfState], a ; change player state to bicycling
ld hl, GotOnBicycleText
call PlayDefaultMusic ; play bike riding music
.printText
jp PrintText
; indirectly used by SURF in StartMenu_Pokemon.surf
ItemUseSurfboard:
ld a, [wWalkBikeSurfState]
ld [wWalkBikeSurfStateCopy], a
cp 2 ; is the player already surfing?
jr z, .tryToStopSurfing
; try to Surf
call IsNextTileShoreOrWater
jp c, SurfingAttemptFailed
ld hl, TilePairCollisionsWater
call CheckForTilePairCollisions
jp c, SurfingAttemptFailed
; surfing
call .makePlayerMoveForward
ld hl, wStatusFlags5
set BIT_SCRIPTED_MOVEMENT_STATE, [hl]
ld a, 2
ld [wWalkBikeSurfState], a ; change player state to surfing
call PlayDefaultMusic ; play surfing music
ld hl, SurfingGotOnText
jp PrintText
.tryToStopSurfing
xor a
ldh [hSpriteIndex], a
ld d, 16 ; talking range in pixels (normal range)
call IsSpriteInFrontOfPlayer2
res BIT_FACE_PLAYER, [hl]
ldh a, [hSpriteIndex]
and a ; is there a sprite in the way?
jr nz, .cannotStopSurfing
ld hl, TilePairCollisionsWater
call CheckForTilePairCollisions
jr c, .cannotStopSurfing
ld hl, wTilesetCollisionPtr ; pointer to list of passable tiles
ld a, [hli]
ld h, [hl]
ld l, a ; hl now points to passable tiles
ld a, [wTileInFrontOfPlayer] ; tile in front of the player
ld b, a
.passableTileLoop
ld a, [hli]
cp b
jr z, .stopSurfing
cp $ff
jr nz, .passableTileLoop
.cannotStopSurfing
ld hl, SurfingNoPlaceToGetOffText
jp PrintText
.stopSurfing
call .makePlayerMoveForward
ld hl, wStatusFlags5
set BIT_SCRIPTED_MOVEMENT_STATE, [hl]
xor a
ld [wWalkBikeSurfState], a ; change player state to walking
dec a
ld [wJoyIgnore], a
call PlayDefaultMusic ; play walking music
jp LoadWalkingPlayerSpriteGraphics
; uses a simulated button press to make the player move forward
.makePlayerMoveForward
ld a, [wPlayerDirection] ; direction the player is going
bit PLAYER_DIR_BIT_UP, a
ld b, PAD_UP
jr nz, .storeSimulatedButtonPress
bit PLAYER_DIR_BIT_DOWN, a
ld b, PAD_DOWN
jr nz, .storeSimulatedButtonPress
bit PLAYER_DIR_BIT_LEFT, a
ld b, PAD_LEFT
jr nz, .storeSimulatedButtonPress
ld b, PAD_RIGHT
.storeSimulatedButtonPress
ld a, b
ld [wSimulatedJoypadStatesEnd], a
xor a
ld [wUnusedSimulatedJoypadStatesMask], a
inc a
ld [wSimulatedJoypadStatesIndex], a
ret
SurfingGotOnText:
text_far _SurfingGotOnText
text_end
SurfingNoPlaceToGetOffText:
text_far _SurfingNoPlaceToGetOffText
text_end
ItemUsePokedex:
predef_jump ShowPokedexMenu
ItemUseEvoStone:
ld a, [wIsInBattle]
and a
jp nz, ItemUseNotTime
ld a, [wWhichPokemon]
push af
ld a, [wCurItem]
ld [wEvoStoneItemID], a
push af
ld a, EVO_STONE_PARTY_MENU
ld [wPartyMenuTypeOrMessageID], a
ld a, $ff
ld [wUpdateSpritesEnabled], a
call DisplayPartyMenu
pop bc
jr c, .canceledItemUse
ld a, b
ld [wCurPartySpecies], a
ld a, TRUE
ld [wForceEvolution], a
ld a, SFX_HEAL_AILMENT
call PlaySoundWaitForCurrent
call WaitForSoundToFinish
callfar TryEvolvingMon ; try to evolve pokemon
ld a, [wEvolutionOccurred]
and a
jr z, .noEffect
pop af
ld [wWhichPokemon], a
ld hl, wNumBagItems
ld a, 1 ; remove 1 stone
ld [wItemQuantity], a
jp RemoveItemFromInventory
.noEffect
call ItemUseNoEffect
.canceledItemUse
xor a
ld [wActionResultOrTookBattleTurn], a ; item not used
pop af
ret
ItemUseVitamin:
ld a, [wIsInBattle]
and a
jp nz, ItemUseNotTime
ItemUseMedicine:
ld a, [wPartyCount]
and a
jp z, .emptyParty
ld a, [wWhichPokemon]
push af
ld a, [wCurItem]
push af
ld a, USE_ITEM_PARTY_MENU
ld [wPartyMenuTypeOrMessageID], a
ld a, $ff
ld [wUpdateSpritesEnabled], a
ld a, [wPseudoItemID]
and a ; using Softboiled?
jr z, .notUsingSoftboiled
; if using softboiled
call GoBackToPartyMenu
jr .getPartyMonDataAddress
.emptyParty
ld hl, .emptyPartyText
xor a
ld [wActionResultOrTookBattleTurn], a ; item use failed
jp PrintText
.emptyPartyText
text "You don't have"
line "any #MON!"
prompt
.notUsingSoftboiled
call DisplayPartyMenu
.getPartyMonDataAddress
jp c, .canceledItemUse
ld hl, wPartyMons
ld bc, PARTYMON_STRUCT_LENGTH
ld a, [wWhichPokemon]
call AddNTimes
ld a, [wWhichPokemon]
ld [wUsedItemOnWhichPokemon], a
ld d, a
ld a, [wCurPartySpecies]
ld e, a
ld [wCurSpecies], a
pop af
ld [wCurItem], a
pop af
ld [wWhichPokemon], a
ld a, [wPseudoItemID]
and a ; using Softboiled?
jr z, .checkItemType
; if using softboiled
ld a, [wWhichPokemon]
cp d ; is the pokemon trying to use softboiled on itself?
jr z, ItemUseMedicine ; if so, force another choice
.checkItemType
ld a, [wCurItem]
cp REVIVE
jr nc, .healHP ; if it's a Revive or Max Revive
cp FULL_HEAL
jr z, .cureStatusAilment ; if it's a Full Heal
cp HP_UP
jp nc, .useVitamin ; if it's a vitamin or Rare Candy
cp FULL_RESTORE
jr nc, .healHP ; if it's a Full Restore or one of the potions
; fall through if it's one of the status-specific healing items
.cureStatusAilment
ld bc, MON_STATUS
add hl, bc ; hl now points to status
ld a, [wCurItem]
lb bc, ANTIDOTE_MSG, 1 << PSN
cp ANTIDOTE
jr z, .checkMonStatus
lb bc, BURN_HEAL_MSG, 1 << BRN
cp BURN_HEAL
jr z, .checkMonStatus
lb bc, ICE_HEAL_MSG, 1 << FRZ
cp ICE_HEAL
jr z, .checkMonStatus
lb bc, AWAKENING_MSG, SLP_MASK
cp AWAKENING
jr z, .checkMonStatus
lb bc, PARALYZ_HEAL_MSG, 1 << PAR
cp PARLYZ_HEAL
jr z, .checkMonStatus
lb bc, FULL_HEAL_MSG, $ff ; Full Heal
.checkMonStatus
ld a, [hl] ; pokemon's status
and c ; does the pokemon have a status ailment the item can cure?
jp z, .healingItemNoEffect
; if the pokemon has a status the item can heal
xor a
ld [hl], a ; remove the status ailment in the party data
ld a, b
ld [wPartyMenuTypeOrMessageID], a ; the message to display for the item used
ld a, [wPlayerMonNumber]
cp d ; is pokemon the item was used on active in battle?
jp nz, .doneHealing
; if it is active in battle
xor a
ld [wBattleMonStatus], a ; remove the status ailment in the in-battle pokemon data
push hl
ld hl, wPlayerBattleStatus3
res BADLY_POISONED, [hl] ; heal Toxic status
pop hl
ld bc, MON_STATS - MON_STATUS
add hl, bc ; hl now points to party stats
ld de, wBattleMonStats
ld bc, NUM_STATS * 2
call CopyData ; copy party stats to in-battle stat data
predef DoubleOrHalveSelectedStats
jp .doneHealing
.healHP
inc hl ; hl = address of current HP
ld a, [hli]
ld b, a
ld [wHPBarOldHP+1], a
ld a, [hl]
ld c, a
ld [wHPBarOldHP], a ; current HP stored at wHPBarOldHP (2 bytes, big-endian)
or b
jr nz, .notFainted
; fainted
ld a, [wCurItem]
cp REVIVE
jr z, .updateInBattleFaintedData
cp MAX_REVIVE
jr z, .updateInBattleFaintedData
jp .healingItemNoEffect
.updateInBattleFaintedData
ld a, [wIsInBattle]
and a
jr z, .compareCurrentHPToMaxHP
push hl
push de
push bc
ld a, [wUsedItemOnWhichPokemon]
ld c, a
ld hl, wPartyFoughtCurrentEnemyFlags
ld b, FLAG_TEST
predef FlagActionPredef
ld a, c
and a
jr z, .next
ld a, [wUsedItemOnWhichPokemon]
ld c, a
ld hl, wPartyGainExpFlags
ld b, FLAG_SET
predef FlagActionPredef
.next
pop bc
pop de
pop hl
jr .compareCurrentHPToMaxHP
.notFainted
ld a, [wCurItem]
cp REVIVE
jp z, .healingItemNoEffect
cp MAX_REVIVE
jp z, .healingItemNoEffect
.compareCurrentHPToMaxHP
push hl
push bc
ld bc, MON_MAXHP - (MON_HP + 1)
add hl, bc ; hl now points to max HP
pop bc
ld a, [hli]
cp b
jr nz, .skipComparingLSB ; no need to compare the LSB's if the MSB's don't match
ld a, [hl]
cp c
.skipComparingLSB
pop hl
jr nz, .notFullHP
; if the pokemon's current HP equals its max HP
ld a, [wCurItem]
cp FULL_RESTORE
jp nz, .healingItemNoEffect
inc hl
inc hl
ld a, [hld] ; status ailment
and a ; does the pokemon have a status ailment?
jp z, .healingItemNoEffect
ld a, FULL_HEAL
ld [wCurItem], a
dec hl
dec hl
dec hl
jp .cureStatusAilment
.notFullHP ; if the pokemon's current HP doesn't equal its max HP
xor a
ld [wLowHealthAlarm], a ;disable low health alarm
ld [wChannelSoundIDs + CHAN5], a
push hl
push de
ld bc, MON_MAXHP - (MON_HP + 1)
add hl, bc ; hl now points to max HP
ld a, [hli]
ld [wHPBarMaxHP+1], a
ld a, [hl]
ld [wHPBarMaxHP], a ; max HP stored at wHPBarMaxHP (2 bytes, big-endian)
ld a, [wPseudoItemID]
and a ; using Softboiled?
jp z, .notUsingSoftboiled2
; if using softboiled
ld hl, wHPBarMaxHP
ld a, [hli]
push af
ld a, [hli]
push af
ld a, [hli]
push af
ld a, [hl]
push af
ld hl, wPartyMon1MaxHP
ld a, [wWhichPokemon]
ld bc, PARTYMON_STRUCT_LENGTH
call AddNTimes
ld a, [hli]
ld [wHPBarMaxHP + 1], a
ldh [hDividend], a
ld a, [hl]
ld [wHPBarMaxHP], a
ldh [hDividend + 1], a
ld a, 5
ldh [hDivisor], a
ld b, 2 ; number of bytes
call Divide ; get 1/5 of max HP of pokemon that used Softboiled
ld bc, (MON_HP + 1) - (MON_MAXHP + 1)
add hl, bc ; hl now points to LSB of current HP of pokemon that used Softboiled
; subtract 1/5 of max HP from current HP of pokemon that used Softboiled
ldh a, [hQuotient + 3]
push af
ld b, a
ld a, [hl]
ld [wHPBarOldHP], a
sub b
ld [hld], a
ld [wHPBarNewHP], a
ldh a, [hQuotient + 2]
ld b, a
ld a, [hl]
ld [wHPBarOldHP+1], a
sbc b
ld [hl], a
ld [wHPBarNewHP+1], a
hlcoord 4, 1
ld a, [wWhichPokemon]
ld bc, 2 * SCREEN_WIDTH
call AddNTimes ; calculate coordinates of HP bar of pokemon that used Softboiled
ld a, SFX_HEAL_HP
call PlaySoundWaitForCurrent
ldh a, [hUILayoutFlags]
set BIT_PARTY_MENU_HP_BAR, a
ldh [hUILayoutFlags], a
ld a, $02
ld [wHPBarType], a
predef UpdateHPBar2 ; animate HP bar decrease of pokemon that used Softboiled
ldh a, [hUILayoutFlags]
res BIT_PARTY_MENU_HP_BAR, a
ldh [hUILayoutFlags], a
pop af
ld b, a ; store heal amount (1/5 of max HP)
ld hl, wHPBarOldHP + 1
pop af
ld [hld], a
pop af
ld [hld], a
pop af
ld [hld], a
pop af
ld [hl], a
jr .addHealAmount
.notUsingSoftboiled2
ld a, [wCurItem]
cp SODA_POP
ld b, 60 ; Soda Pop heal amount
jr z, .addHealAmount
ld b, 80 ; Lemonade heal amount
jr nc, .addHealAmount
cp FRESH_WATER
ld b, 50 ; Fresh Water heal amount
jr z, .addHealAmount
cp SUPER_POTION
ld b, 200 ; Hyper Potion heal amount
jr c, .addHealAmount
ld b, 50 ; Super Potion heal amount
jr z, .addHealAmount
ld b, 20 ; Potion heal amount
.addHealAmount
pop de
pop hl
ld a, [hl]
add b
ld [hld], a
ld [wHPBarNewHP], a
ld a, [hl]
ld [wHPBarNewHP+1], a
jr nc, .noCarry
inc [hl]
ld a, [hl]
ld [wHPBarNewHP + 1], a
.noCarry
push de
inc hl
ld d, h
ld e, l ; de now points to current HP
ld hl, (MON_MAXHP + 1) - (MON_HP + 1)
add hl, de ; hl now points to max HP
ld a, [wCurItem]
cp REVIVE
jr z, .setCurrentHPToHalfMaxHP
ld a, [hld]
ld b, a
ld a, [de]
sub b
dec de
ld b, [hl]
ld a, [de]
sbc b
jr nc, .setCurrentHPToMaxHp ; if current HP exceeds max HP after healing
ld a, [wCurItem]
cp HYPER_POTION
jr c, .setCurrentHPToMaxHp ; if using a Full Restore or Max Potion
cp MAX_REVIVE
jr z, .setCurrentHPToMaxHp ; if using a Max Revive
jr .updateInBattleData
.setCurrentHPToHalfMaxHP
dec hl
dec de
ld a, [hli]
srl a
ld [de], a
ld [wHPBarNewHP+1], a
ld a, [hl]
rr a
inc de
ld [de], a
ld [wHPBarNewHP], a
dec de
jr .doneHealingPartyHP
.setCurrentHPToMaxHp
ld a, [hli]
ld [de], a
ld [wHPBarNewHP+1], a
inc de
ld a, [hl]
ld [de], a
ld [wHPBarNewHP], a
dec de
.doneHealingPartyHP ; done updating the pokemon's current HP in the party data structure
ld a, [wCurItem]
cp FULL_RESTORE
jr nz, .updateInBattleData
ld bc, MON_STATUS - (MON_MAXHP + 1)
add hl, bc
xor a
ld [hl], a ; remove the status ailment in the party data
.updateInBattleData
ld h, d
ld l, e
pop de
ld a, [wPlayerMonNumber]
cp d ; is pokemon the item was used on active in battle?
jr nz, .calculateHPBarCoords
; copy party HP to in-battle HP
ld a, [hli]
ld [wBattleMonHP], a
ld a, [hld]
ld [wBattleMonHP + 1], a
ld a, [wCurItem]
cp FULL_RESTORE
jr nz, .calculateHPBarCoords
xor a
ld [wBattleMonStatus], a ; remove the status ailment in the in-battle pokemon data
.calculateHPBarCoords
hlcoord 4, -1
ld bc, 2 * SCREEN_WIDTH
inc d
.calculateHPBarCoordsLoop
add hl, bc
dec d
jr nz, .calculateHPBarCoordsLoop
jr .doneHealing
.healingItemNoEffect
call ItemUseNoEffect
jp .done
.doneHealing
ld a, [wPseudoItemID]
and a ; using Softboiled?
jr nz, .skipRemovingItem ; no item to remove if using Softboiled
push hl
call RemoveUsedItem
pop hl
.skipRemovingItem
ld a, [wCurItem]
cp FULL_RESTORE
jr c, .playStatusAilmentCuringSound
cp FULL_HEAL
jr z, .playStatusAilmentCuringSound
ld a, SFX_HEAL_HP
call PlaySoundWaitForCurrent
ldh a, [hUILayoutFlags]
set BIT_PARTY_MENU_HP_BAR, a
ldh [hUILayoutFlags], a
ld a, $02
ld [wHPBarType], a
predef UpdateHPBar2 ; animate the HP bar lengthening
ldh a, [hUILayoutFlags]
res BIT_PARTY_MENU_HP_BAR, a
ldh [hUILayoutFlags], a
ld a, REVIVE_MSG
ld [wPartyMenuTypeOrMessageID], a
ld a, [wCurItem]
cp REVIVE
jr z, .showHealingItemMessage
cp MAX_REVIVE
jr z, .showHealingItemMessage
ld a, POTION_MSG
ld [wPartyMenuTypeOrMessageID], a
jr .showHealingItemMessage
.playStatusAilmentCuringSound
ld a, SFX_HEAL_AILMENT
call PlaySoundWaitForCurrent
.showHealingItemMessage
xor a
ldh [hAutoBGTransferEnabled], a
call ClearScreen
dec a
ld [wUpdateSpritesEnabled], a
call RedrawPartyMenu ; redraws the party menu and displays the message
ld a, 1
ldh [hAutoBGTransferEnabled], a
ld c, 50
call DelayFrames
call WaitForTextScrollButtonPress
jr .done
.canceledItemUse
xor a
ld [wActionResultOrTookBattleTurn], a ; item use failed
pop af
pop af
.done
ld a, [wPseudoItemID]
and a ; using Softboiled?
ret nz ; if so, return
call GBPalWhiteOut
call z, RunDefaultPaletteCommand
ld a, [wIsInBattle]
and a
ret nz
jp ReloadMapData
.useVitamin
push hl
ld a, [hl]
ld [wCurSpecies], a
ld [wPokedexNum], a
ld bc, MON_LEVEL
add hl, bc ; hl now points to level
ld a, [hl] ; a = level
ld [wCurEnemyLevel], a ; store level
call GetMonHeader
push de
ld a, d
ld hl, wPartyMonNicks
call GetPartyMonName
pop de
pop hl
ld a, [wCurItem]
cp RARE_CANDY
jp z, .useRareCandy
push hl
sub HP_UP
add a
ld bc, MON_HP_EXP
add hl, bc
add l
ld l, a
jr nc, .noCarry2
inc h
.noCarry2
ld a, 10
ld b, a
ld a, [hl] ; a = MSB of stat experience of the appropriate stat
cp 100 ; is there already at least 25600 (256 * 100) stat experience?
jr nc, .vitaminNoEffect ; if so, vitamins can't add any more
add b ; add 2560 (256 * 10) stat experience
jr nc, .noCarry3 ; a carry should be impossible here, so this will always jump
ld a, 255
.noCarry3
ld [hl], a
pop hl
call .recalculateStats
ld hl, VitaminStats
ld a, [wCurItem]
sub HP_UP - 1
ld c, a
.statNameLoop ; loop to get the address of the name of the stat the vitamin increases
dec c
jr z, .gotStatName
.statNameInnerLoop
ld a, [hli]
ld b, a
ld a, '@'
cp b
jr nz, .statNameInnerLoop
jr .statNameLoop
.gotStatName
ld de, wStringBuffer
ld bc, STAT_NAME_LENGTH
call CopyData ; copy the stat's name to wStringBuffer
ld a, SFX_HEAL_AILMENT
call PlaySound
ld hl, VitaminStatRoseText
call PrintText
jp RemoveUsedItem
.vitaminNoEffect
pop hl
ld hl, VitaminNoEffectText
call PrintText
jp GBPalWhiteOut
.recalculateStats
ld bc, MON_STATS
add hl, bc
ld d, h
ld e, l ; de now points to stats
ld bc, (MON_EXP + 2) - MON_STATS
add hl, bc ; hl now points to LSB of experience
ld b, 1
jp CalcStats ; recalculate stats
.useRareCandy
push hl
ld bc, MON_LEVEL
add hl, bc ; hl now points to level
ld a, [hl] ; a = level
cp MAX_LEVEL
jr z, .vitaminNoEffect ; can't raise level above 100
inc a
ld [hl], a ; store incremented level
ld [wCurEnemyLevel], a
push hl
push de
ld d, a
callfar CalcExperience ; calculate experience for next level and store it at hExperience
pop de
pop hl
ld bc, MON_EXP - MON_LEVEL
add hl, bc ; hl now points to MSB of experience
; update experience to minimum for new level
ldh a, [hExperience]
ld [hli], a
ldh a, [hExperience + 1]
ld [hli], a
ldh a, [hExperience + 2]
ld [hl], a
pop hl
ld a, [wWhichPokemon]
push af
ld a, [wCurItem]
push af
push de
push hl
ld bc, MON_MAXHP
add hl, bc ; hl now points to MSB of max HP
ld a, [hli]
ld b, a
ld c, [hl]
pop hl
push bc
push hl
call .recalculateStats
pop hl
ld bc, (MON_MAXHP + 1)
add hl, bc ; hl now points to LSB of max HP
pop bc
ld a, [hld]
sub c
ld c, a
ld a, [hl]
sbc b
ld b, a ; bc = the amount of max HP gained from leveling up
; add the amount gained to the current HP
ld de, (MON_HP + 1) - MON_MAXHP
add hl, de ; hl now points to LSB of current HP
ld a, [hl]
add c
ld [hld], a
ld a, [hl]
adc b
ld [hl], a
ld a, RARE_CANDY_MSG
ld [wPartyMenuTypeOrMessageID], a
call RedrawPartyMenu
pop de
ld a, d
ld [wWhichPokemon], a
ld a, e
ld [wPokedexNum], a
xor a ; PLAYER_PARTY_DATA
ld [wMonDataLocation], a
call LoadMonData
ld d, LEVEL_UP_STATS_BOX
callfar PrintStatsBox
call WaitForTextScrollButtonPress
xor a ; PLAYER_PARTY_DATA
ld [wMonDataLocation], a
predef LearnMoveFromLevelUp
xor a
ld [wForceEvolution], a
callfar TryEvolvingMon
ld a, $01
ld [wUpdateSpritesEnabled], a
pop af
ld [wCurItem], a
pop af
ld [wWhichPokemon], a
jp RemoveUsedItem
VitaminStatRoseText:
text_far _VitaminStatRoseText
text_end
VitaminNoEffectText:
text_far _VitaminNoEffectText
text_end
INCLUDE "data/battle/stat_names.asm"
; for BOULDERBADGE when used from the
; ITEM window, which corresponds to
; SAFARI_BAIT during Safari Game encounters
ItemUseBait:
ld hl, ThrewBaitText
call PrintText
ld hl, wEnemyMonActualCatchRate
srl [hl] ; halve catch rate
ld a, BAIT_ANIM
ld hl, wSafariBaitFactor
ld de, wSafariEscapeFactor
jr BaitRockCommon
; for CASCADEBADGE when used from the
; ITEM window, which corresponds to
; SAFARI_ROCK during Safari Game encounters
ItemUseRock:
ld hl, ThrewRockText
call PrintText
ld hl, wEnemyMonActualCatchRate
ld a, [hl]
add a ; double catch rate
jr nc, .noCarry
ld a, $ff
.noCarry
ld [hl], a
ld a, ROCK_ANIM
ld hl, wSafariEscapeFactor
ld de, wSafariBaitFactor
BaitRockCommon:
ld [wAnimationID], a
xor a
ld [wAnimationType], a
ldh [hWhoseTurn], a
ld [de], a ; zero escape factor (for bait), zero bait factor (for rock)
.randomLoop ; loop until a random number less than 5 is generated
call Random
and 7
cp 5
jr nc, .randomLoop
inc a ; increment the random number, giving a range from 1 to 5 inclusive
ld b, a
ld a, [hl]
add b ; increase bait factor (for bait), increase escape factor (for rock)
jr nc, .noCarry
ld a, $ff
.noCarry
ld [hl], a
predef MoveAnimation ; do animation
ld c, 70
jp DelayFrames
ThrewBaitText:
text_far _ThrewBaitText
text_end
ThrewRockText:
text_far _ThrewRockText
text_end
; indirectly used by DIG in StartMenu_Pokemon.dig
ItemUseEscapeRope:
ld a, [wIsInBattle]
and a
jr nz, .notUsable
ld a, [wCurMap]
cp AGATHAS_ROOM
jr z, .notUsable
ld a, [wCurMapTileset]
ld b, a
ld hl, EscapeRopeTilesets
.loop
ld a, [hli]
cp $ff
jr z, .notUsable
cp b
jr nz, .loop
ld hl, wStatusFlags6
set BIT_FLY_WARP, [hl]
set BIT_ESCAPE_WARP, [hl]
ld hl, wStatusFlags4
res BIT_NO_BATTLES, [hl]
ResetEvent EVENT_IN_SAFARI_ZONE
xor a
ld [wNumSafariBalls], a
ld [wSafariZoneGateCurScript], a ; SCRIPT_SAFARIZONEGATE_DEFAULT
inc a
ld [wEscapedFromBattle], a
ld [wActionResultOrTookBattleTurn], a ; item used
ld a, [wPseudoItemID]
and a ; using Dig?
ret nz ; if so, return
call ItemUseReloadOverworldData
ld c, 30
call DelayFrames
jp RemoveUsedItem
.notUsable
jp ItemUseNotTime
INCLUDE "data/tilesets/escape_rope_tilesets.asm"
ItemUseRepel:
ld b, 100
ItemUseRepelCommon:
ld a, [wIsInBattle]
and a
jp nz, ItemUseNotTime
ld a, b
ld [wRepelRemainingSteps], a
jp PrintItemUseTextAndRemoveItem
; handles X Accuracy item
ItemUseXAccuracy:
ld a, [wIsInBattle]
and a
jp z, ItemUseNotTime
ld hl, wPlayerBattleStatus2
set USING_X_ACCURACY, [hl] ; X Accuracy bit
jp PrintItemUseTextAndRemoveItem
; This function is bugged and never works. It always jumps to ItemUseNotTime.
; The Card Key is handled in a different way.
ItemUseCardKey:
xor a
ld [wUnusedCardKeyGateID], a
call GetTileAndCoordsInFrontOfPlayer
ld a, [GetTileAndCoordsInFrontOfPlayer]
cp $18
jr nz, .next0
ld hl, CardKeyTable1
jr .next1
.next0
cp $24
jr nz, .next2
ld hl, CardKeyTable2
jr .next1
.next2
cp $5e
jp nz, ItemUseNotTime
ld hl, CardKeyTable3
.next1
ld a, [wCurMap]
ld b, a
.loop
ld a, [hli]
cp -1
jp z, ItemUseNotTime
cp b
jr nz, .nextEntry1
ld a, [hli]
cp d
jr nz, .nextEntry2
ld a, [hli]
cp e
jr nz, .nextEntry3
ld a, [hl]
ld [wUnusedCardKeyGateID], a
jr .done
.nextEntry1
inc hl
.nextEntry2
inc hl
.nextEntry3
inc hl
jr .loop
.done
ld hl, ItemUseText00
call PrintText
ld hl, wStatusFlags1
set BIT_UNUSED_CARD_KEY, [hl] ; never checked
ret
INCLUDE "data/events/card_key_coords.asm"
ItemUsePokeDoll:
ld a, [wIsInBattle]
dec a
jp nz, ItemUseNotTime
ld a, $01
ld [wEscapedFromBattle], a
jp PrintItemUseTextAndRemoveItem
ItemUseGuardSpec:
ld a, [wIsInBattle]
and a
jp z, ItemUseNotTime
ld hl, wPlayerBattleStatus2
set PROTECTED_BY_MIST, [hl] ; Mist bit
jp PrintItemUseTextAndRemoveItem
ItemUseSuperRepel:
ld b, 200
jp ItemUseRepelCommon
ItemUseMaxRepel:
ld b, 250
jp ItemUseRepelCommon
ItemUseDireHit:
ld a, [wIsInBattle]
and a
jp z, ItemUseNotTime
ld hl, wPlayerBattleStatus2
set GETTING_PUMPED, [hl] ; Focus Energy bit
jp PrintItemUseTextAndRemoveItem
ItemUseXStat:
ld a, [wIsInBattle]
and a
jr nz, .inBattle
call ItemUseNotTime
ld a, 2
ld [wActionResultOrTookBattleTurn], a ; item not used
ret
.inBattle
ld hl, wPlayerMoveNum
ld a, [hli]
push af ; save [wPlayerMoveNum]
ld a, [hl]
push af ; save [wPlayerMoveEffect]
push hl
ld a, [wCurItem]
sub X_ATTACK - ATTACK_UP1_EFFECT
ld [hl], a ; store player move effect
call PrintItemUseTextAndRemoveItem
ld a, XSTATITEM_ANIM ; X stat item animation ID
ld [wPlayerMoveNum], a
call LoadScreenTilesFromBuffer1 ; restore saved screen
call Delay3
xor a
ldh [hWhoseTurn], a ; set turn to player's turn
farcall StatModifierUpEffect ; do stat increase move
pop hl
pop af
ld [hld], a ; restore [wPlayerMoveEffect]
pop af
ld [hl], a ; restore [wPlayerMoveNum]
ret
ItemUsePokeFlute:
ld a, [wIsInBattle]
and a
jr nz, .inBattle
; if not in battle
call ItemUseReloadOverworldData
ld a, [wCurMap]
cp ROUTE_12
jr nz, .notRoute12
CheckEvent EVENT_BEAT_ROUTE12_SNORLAX
jr nz, .noSnorlaxToWakeUp
; if the player hasn't beaten Route 12 Snorlax
ld hl, Route12SnorlaxFluteCoords
call ArePlayerCoordsInArray
jr nc, .noSnorlaxToWakeUp
ld hl, PlayedFluteHadEffectText
call PrintText
SetEvent EVENT_FIGHT_ROUTE12_SNORLAX
ret
.notRoute12
cp ROUTE_16
jr nz, .noSnorlaxToWakeUp
CheckEvent EVENT_BEAT_ROUTE16_SNORLAX
jr nz, .noSnorlaxToWakeUp
; if the player hasn't beaten Route 16 Snorlax
ld hl, Route16SnorlaxFluteCoords
call ArePlayerCoordsInArray
jr nc, .noSnorlaxToWakeUp
ld hl, PlayedFluteHadEffectText
call PrintText
SetEvent EVENT_FIGHT_ROUTE16_SNORLAX
ret
.noSnorlaxToWakeUp
ld hl, PlayedFluteNoEffectText
jp PrintText
.inBattle
xor a
ld [wWereAnyMonsAsleep], a
ld b, ~SLP_MASK
ld hl, wPartyMon1Status
call WakeUpEntireParty
ld a, [wIsInBattle]
dec a ; is it a trainer battle?
jr z, .skipWakingUpEnemyParty
; if it's a trainer battle
ld hl, wEnemyMon1Status
call WakeUpEntireParty
.skipWakingUpEnemyParty
ld hl, wBattleMonStatus
ld a, [hl]
and b ; remove Sleep status
ld [hl], a
ld hl, wEnemyMonStatus
ld a, [hl]
and b ; remove Sleep status
ld [hl], a
call LoadScreenTilesFromBuffer2 ; restore saved screen
ld a, [wWereAnyMonsAsleep]
and a ; were any pokemon asleep before playing the flute?
ld hl, PlayedFluteNoEffectText
jp z, PrintText ; if no pokemon were asleep
; if some pokemon were asleep
ld hl, PlayedFluteHadEffectText
call PrintText
ld a, [wLowHealthAlarm]
and $80
jr nz, .skipMusic
call WaitForSoundToFinish ; wait for sound to end
farcall Music_PokeFluteInBattle ; play in-battle pokeflute music
.musicWaitLoop ; wait for music to finish playing
ld a, [wChannelSoundIDs + CHAN7]
and a ; music off?
jr nz, .musicWaitLoop
.skipMusic
ld hl, FluteWokeUpText
jp PrintText
; wakes up all party pokemon
; INPUT:
; hl must point to status of first pokemon in party (player's or enemy's)
; b must equal ~SLP
; [wWereAnyMonsAsleep] should be initialized to 0
; OUTPUT:
; [wWereAnyMonsAsleep]: set to 1 if any pokemon were asleep
WakeUpEntireParty:
ld de, PARTYMON_STRUCT_LENGTH
ld c, PARTY_LENGTH
.loop
ld a, [hl]
push af
and SLP_MASK
jr z, .notAsleep
ld a, 1
ld [wWereAnyMonsAsleep], a ; indicate that a pokemon had to be woken up
.notAsleep
pop af
and b ; remove Sleep status
ld [hl], a
add hl, de
dec c
jr nz, .loop
ret
Route12SnorlaxFluteCoords:
dbmapcoord 9, 62 ; one space West of Snorlax
dbmapcoord 10, 61 ; one space North of Snorlax
dbmapcoord 10, 63 ; one space South of Snorlax
dbmapcoord 11, 62 ; one space East of Snorlax
db -1 ; end
Route16SnorlaxFluteCoords:
dbmapcoord 27, 10 ; one space East of Snorlax
dbmapcoord 25, 10 ; one space West of Snorlax
db -1 ; end
PlayedFluteNoEffectText:
text_far _PlayedFluteNoEffectText
text_end
FluteWokeUpText:
text_far _FluteWokeUpText
text_end
PlayedFluteHadEffectText:
text_far _PlayedFluteHadEffectText
text_promptbutton
text_asm
ld a, [wIsInBattle]
and a
jr nz, .done
; play out-of-battle pokeflute music
ld a, SFX_STOP_ALL_MUSIC
call PlaySound
ld a, SFX_POKEFLUTE
ld c, BANK(SFX_Pokeflute)
call PlayMusic
.musicWaitLoop ; wait for music to finish playing
ld a, [wChannelSoundIDs + CHAN3]
cp SFX_POKEFLUTE
jr z, .musicWaitLoop
call PlayDefaultMusic ; start playing normal music again
.done
jp TextScriptEnd ; end text
ItemUseCoinCase:
ld a, [wIsInBattle]
and a
jp nz, ItemUseNotTime
ld hl, CoinCaseNumCoinsText
jp PrintText
CoinCaseNumCoinsText:
text_far _CoinCaseNumCoinsText
text_end
ItemUseOldRod:
call FishingInit
jp c, ItemUseNotTime
lb bc, 5, MAGIKARP
ld a, $1 ; set bite
jr RodResponse
ItemUseGoodRod:
call FishingInit
jp c, ItemUseNotTime
.RandomLoop
call Random
srl a
jr c, .SetBite
and %11
cp 2
jr nc, .RandomLoop
; choose which monster appears
ld hl, GoodRodMons
add a
ld c, a
ld b, 0
add hl, bc
ld b, [hl]
inc hl
ld c, [hl]
and a
.SetBite
ld a, 0
rla
xor 1
jr RodResponse
INCLUDE "data/wild/good_rod.asm"
ItemUseSuperRod:
call FishingInit
jp c, ItemUseNotTime
call ReadSuperRodData
ld a, e
RodResponse:
ld [wRodResponse], a
dec a ; is there a bite?
jr nz, .next
; if yes, store level and species data
ld a, 1
ld [wMoveMissed], a
ld a, b ; level
ld [wCurEnemyLevel], a
ld a, c ; species
ld [wCurOpponent], a
.next
ld hl, wWalkBikeSurfState
ld a, [hl] ; store the value in a
push af
push hl
ld [hl], 0
farcall FishingAnim
pop hl
pop af
ld [hl], a
ret
; checks if fishing is possible and if so, runs initialization code common to all rods
; unsets carry if fishing is possible, sets carry if not
FishingInit:
ld a, [wIsInBattle]
and a
jr z, .notInBattle
scf ; can't fish during battle
ret
.notInBattle
call IsNextTileShoreOrWater
ret c
ld a, [wWalkBikeSurfState]
cp 2 ; Surfing?
jr z, .surfing
