; restores bonus PP (from PP Ups) when healing at a pokemon center
; also, when a PP Up is used, it increases the current PP by one PP Up bonus
; INPUT:
; [wWhichPokemon] = index of pokemon in party
; [wCurrentMenuItem] = index of move (when using a PP Up)
RestoreBonusPP:
ld hl, wPartyMon1Moves
ld bc, PARTYMON_STRUCT_LENGTH
ld a, [wWhichPokemon]
call AddNTimes
push hl
ld de, wNormalMaxPPList - 1
predef LoadMovePPs ; loads the normal max PP of each of the pokemon's moves to wNormalMaxPPList
pop hl
ld c, MON_PP - MON_MOVES
ld b, 0
add hl, bc ; hl now points to move 1 PP
ld de, wNormalMaxPPList
ld b, 0 ; initialize move counter to zero
; loop through the pokemon's moves
.loop
inc b
ld a, b
cp 5 ; reached the end of the pokemon's moves?
ret z ; if so, return
ld a, [wUsingPPUp]
dec a ; using a PP Up?
jr nz, .skipMenuItemIDCheck
; if using a PP Up, check if this is the move it's being used on
ld a, [wCurrentMenuItem]
inc a
cp b
jr nz, .nextMove
.skipMenuItemIDCheck
ld a, [hl]
and PP_UP_MASK
call nz, AddBonusPP ; if so, add bonus PP
.nextMove
inc hl
inc de
jr .loop
; adds bonus PP from PP Ups to current PP
; 1/5 of normal max PP (capped at 7) is added for each PP Up
; INPUT:
; [de] = normal max PP
; [hl] = move PP
AddBonusPP:
push bc
ld a, [de] ; normal max PP of move
ldh [hDividend + 3], a
xor a
ldh [hDividend], a
ldh [hDividend + 1], a
ldh [hDividend + 2], a
ld a, 5
ldh [hDivisor], a
ld b, 4
call Divide
ld a, [hl] ; move PP
ld b, a
swap a
and %00001111
srl a
srl a
ld c, a ; c = number of PP Ups used
.loop
ldh a, [hQuotient + 3]
cp 8 ; is the amount greater than or equal to 8?
jr c, .addAmount
ld a, 7 ; cap the amount at 7
.addAmount
add b
ld b, a
ld a, [wUsingPPUp]
dec a ; is the player using a PP Up right now?
jr z, .done ; if so, only add the bonus once
dec c
jr nz, .loop
.done
ld [hl], b
pop bc
ret
; gets max PP of a pokemon's move (including PP from PP Ups)
; INPUT:
; [wWhichPokemon] = index of pokemon within party/box
; [wMonDataLocation] = pokemon source
; 00: player's party
; 01: enemy's party
; 02: current box
; 03: daycare
; 04: player's in-battle pokemon
; [wCurrentMenuItem] = move index
; OUTPUT:
; [wMaxPP] = max PP
GetMaxPP:
ld a, [wMonDataLocation]
and a
ld hl, wPartyMon1Moves
ld bc, PARTYMON_STRUCT_LENGTH
jr z, .sourceWithMultipleMon
ld hl, wEnemyMon1Moves
dec a
jr z, .sourceWithMultipleMon
ld hl, wBoxMon1Moves
ld bc, BOXMON_STRUCT_LENGTH
dec a
jr z, .sourceWithMultipleMon
ld hl, wDayCareMonMoves
dec a
jr z, .sourceWithOneMon
ld hl, wBattleMonMoves ; player's in-battle pokemon
.sourceWithOneMon
call GetSelectedMoveOffset2
jr .next
.sourceWithMultipleMon
call GetSelectedMoveOffset
.next
ld a, [hl]
dec a
push hl
ld hl, Moves
ld bc, MOVE_LENGTH
call AddNTimes
ld de, wMoveData
ld a, BANK(Moves)
call FarCopyData
ld de, wMoveData + MOVE_PP
ld a, [de]
ld b, a ; b = normal max PP
pop hl
push bc
ld bc, MON_PP - MON_MOVES ; PP offset if not player's in-battle pokemon data
ld a, [wMonDataLocation]
cp 4 ; player's in-battle pokemon?
jr nz, .addPPOffset
ld bc, wBattleMonPP - wBattleMonMoves ; PP offset if player's in-battle pokemon data
.addPPOffset
add hl, bc
ld a, [hl] ; a = current PP
and PP_UP_MASK
pop bc
or b ; place normal max PP in 6 lower bits of a
ASSERT wMoveData + MOVE_PP + 1 == wPPUpCountAndMaxPP
ld h, d
ld l, e
inc hl ; hl = wPPUpCountAndMaxPP
ld [hl], a
xor a ; add the bonus for the existing PP Up count
ld [wUsingPPUp], a
call AddBonusPP ; add bonus PP from PP Ups
ld a, [hl]
and PP_MASK
ld [wMaxPP], a ; store max PP
ret
GetSelectedMoveOffset:
ld a, [wWhichPokemon]
call AddNTimes
GetSelectedMoveOffset2:
ld a, [wCurrentMenuItem]
ld c, a
ld b, 0
add hl, bc
ret
; confirms the item toss and then tosses the item
; INPUT:
; hl = address of inventory (either wNumBagItems or wNumBoxItems)
; [wCurItem] = item ID
; [wWhichPokemon] = index of item within inventory
; [wItemQuantity] = quantity to toss
; OUTPUT:
; clears carry flag if the item is tossed, sets carry flag if not
TossItem_::
push hl
ld a, [wCurItem]
call IsItemHM
pop hl
jr c, .tooImportantToToss
push hl
call IsKeyItem_
ld a, [wIsKeyItem]
pop hl
and a
jr nz, .tooImportantToToss
push hl
ld a, [wCurItem]
ld [wNamedObjectIndex], a
call GetItemName
call CopyToStringBuffer
ld hl, IsItOKToTossItemText
call PrintText
hlcoord 14, 7
lb bc, 8, 15
ld a, TWO_OPTION_MENU
ld [wTextBoxID], a
call DisplayTextBoxID ; yes/no menu
ld a, [wMenuExitMethod]
cp CHOSE_SECOND_ITEM
pop hl
scf
ret z ; return if the player chose No
; if the player chose Yes
push hl
ld a, [wWhichPokemon]
call RemoveItemFromInventory
ld a, [wCurItem]
ld [wNamedObjectIndex], a
call GetItemName
call CopyToStringBuffer
ld hl, ThrewAwayItemText
call PrintText
pop hl
and a
ret
.tooImportantToToss
push hl
ld hl, TooImportantToTossText
call PrintText
pop hl
scf
ret
ThrewAwayItemText:
text_far _ThrewAwayItemText
text_end
IsItOKToTossItemText:
text_far _IsItOKToTossItemText
text_end
TooImportantToTossText:
text_far _TooImportantToTossText
text_end
; checks if an item is a key item
; INPUT:
; [wCurItem] = item ID
; OUTPUT:
; [wIsKeyItem] = result
; 00: item is not key item
; 01: item is key item
IsKeyItem_::
ld a, $01
ld [wIsKeyItem], a
ld a, [wCurItem]
cp HM01 ; is the item an HM or TM?
jr nc, .checkIfItemIsHM
; if the item is not an HM or TM
push af
ld hl, KeyItemFlags
ld de, wBuffer
ld bc, 15 ; only 11 bytes are actually used
ASSERT 15 >= (NUM_ITEMS + 7) / 8
call CopyData
pop af
dec a
ld c, a
ld hl, wBuffer
ld b, FLAG_TEST
predef FlagActionPredef
ld a, c
and a
ret nz
.checkIfItemIsHM
ld a, [wCurItem]
call IsItemHM
ret c
xor a
ld [wIsKeyItem], a
ret
INCLUDE "data/items/key_items.asm"
; store the new mon in the first slot, shifting all existing box data down
SendNewMonToBox:
ld de, wBoxCount
ld a, [de]
inc a
ld [de], a
ld a, [wCurPartySpecies]
ld [wCurSpecies], a
ld c, a
.shiftSpeciesLoop
inc de
ld a, [de]
ld b, a
ld a, c
ld c, b
ld [de], a
cp -1
jr nz, .shiftSpeciesLoop
call GetMonHeader
ld hl, wBoxMonOT
ld bc, NAME_LENGTH
ld a, [wBoxCount]
dec a
jr z, .skipOTshift ; if the box was empty, there is nothing to shift
dec a
call AddNTimes
push hl
ld bc, NAME_LENGTH
add hl, bc
ld d, h
ld e, l
pop hl
ld a, [wBoxCount]
dec a
ld b, a
.shiftMonOTLoop
push bc
push hl
ld bc, NAME_LENGTH
call CopyData
pop hl
ld d, h
ld e, l
ld bc, -NAME_LENGTH
add hl, bc
pop bc
dec b
jr nz, .shiftMonOTLoop
.skipOTshift
ld hl, wPlayerName
ld de, wBoxMon1OT
ld bc, NAME_LENGTH
call CopyData
ld a, [wBoxCount]
dec a
jr z, .skipNickShift
ld hl, wBoxMonNicks
ld bc, NAME_LENGTH
dec a
call AddNTimes
push hl
ld bc, NAME_LENGTH
add hl, bc
ld d, h
ld e, l
pop hl
ld a, [wBoxCount]
dec a
ld b, a
.shiftNickLoop
push bc
push hl
ld bc, NAME_LENGTH
call CopyData
pop hl
ld d, h
ld e, l
ld bc, -NAME_LENGTH
add hl, bc
pop bc
dec b
jr nz, .shiftNickLoop
.skipNickShift
ld hl, wBoxMon1Nick
ld a, NAME_MON_SCREEN
ld [wNamingScreenType], a
predef AskName
ld a, [wBoxCount]
dec a
jr z, .skipMonDataShift
ld hl, wBoxMons
ld bc, BOXMON_STRUCT_LENGTH
dec a
call AddNTimes
push hl
ld bc, BOXMON_STRUCT_LENGTH
add hl, bc
ld d, h
ld e, l
pop hl
ld a, [wBoxCount]
dec a
ld b, a
.shiftMonDataLoop
push bc
push hl
ld bc, BOXMON_STRUCT_LENGTH
call CopyData
pop hl
ld d, h
ld e, l
ld bc, -BOXMON_STRUCT_LENGTH
add hl, bc
pop bc
dec b
jr nz, .shiftMonDataLoop
.skipMonDataShift
ld a, [wEnemyMonLevel]
ld [wEnemyMonBoxLevel], a
ld hl, wEnemyMon
ld de, wBoxMon1
ld bc, wEnemyMonDVs - wEnemyMon
call CopyData
ld hl, wPlayerID
ld a, [hli]
ld [de], a
inc de
ld a, [hl]
ld [de], a
inc de
push de
ld a, [wCurEnemyLevel]
ld d, a
callfar CalcExperience
pop de
ldh a, [hExperience]
ld [de], a
inc de
ldh a, [hExperience + 1]
ld [de], a
inc de
ldh a, [hExperience + 2]
ld [de], a
inc de
xor a
ld b, NUM_STATS * 2
.statLoop
ld [de], a
inc de
dec b
jr nz, .statLoop
ld hl, wEnemyMonDVs
ld a, [hli]
ld [de], a
inc de
ld a, [hli]
ld [de], a
ld hl, wEnemyMonPP
ld b, NUM_MOVES
.movePPLoop
ld a, [hli]
inc de
ld [de], a
dec b
jr nz, .movePPLoop
ret
; checks if the tile in front of the player is a shore or water tile
; used for surfing and fishing
; unsets carry if it is, sets carry if not
IsNextTileShoreOrWater:
ld a, [wCurMapTileset]
ld hl, WaterTilesets
ld de, 1
call IsInArray
jr nc, .notShoreOrWater
ld a, [wCurMapTileset]
cp SHIP_PORT ; Vermilion Dock tileset
ld a, [wTileInFrontOfPlayer] ; tile in front of player
jr z, .skipShoreTiles ; if it's the Vermilion Dock tileset
cp $48 ; eastern shore tile in Safari Zone
jr z, .shoreOrWater
cp $32 ; usual eastern shore tile
jr z, .shoreOrWater
.skipShoreTiles
cp $14 ; water tile
jr z, .shoreOrWater
.notShoreOrWater
scf
ret
.shoreOrWater
and a
ret
INCLUDE "data/tilesets/water_tilesets.asm"
ReadSuperRodData:
; return e = 2 if no fish on this map
; return e = 1 if a bite, bc = level,species
; return e = 0 if no bite
ld a, [wCurMap]
ld de, 3 ; each fishing group is three bytes wide
ld hl, SuperRodData
call IsInArray
jr c, .ReadFishingGroup
ld e, $2 ; $2 if no fishing groups found
ret
.ReadFishingGroup
; hl points to the fishing group entry in the index
inc hl ; skip map id
; read fishing group address
ld a, [hli]
ld h, [hl]
ld l, a
ld b, [hl] ; how many mons in group
inc hl ; point to data
ld e, $0 ; no bite yet
.RandomLoop
call Random
srl a
ret c ; 50% chance of no battle
and %11 ; 2-bit random number
cp b
jr nc, .RandomLoop ; if a is greater than the number of mons, regenerate
; get the mon
add a
ld c, a
ld b, $0
add hl, bc
ld b, [hl] ; level
inc hl
ld c, [hl] ; species
ld e, $1 ; $1 if there's a bite
ret
