; BEGIN_INCLUDE \\?\M:\Code\Research\pokered-master\engine\flag_action.asm
FlagActionPredef:
call GetPredefRegisters
FlagAction:
; Perform action b on bit c
; in the bitfield at hl.
; 0: reset
; 1: set
; 2: read
; Return the result in c.
push hl
push de
push bc
; bit
ld a, c
ld d, a
and 7
ld e, a
; byte
ld a, d
srl a
srl a
srl a
add l
ld l, a
jr nc, .ok
inc h
.ok
; d = 1 << e (bitmask)
inc e
ld d, 1
.shift
dec e
jr z, .shifted
sla d
jr .shift
.shifted
ld a, b
and a
jr z, .reset
cp FLAG_TEST
jr z, .read
; set
ld b, [hl]
ld a, d
or b
ld [hl], a
jr .done
.reset
ld b, [hl]
ld a, d
xor $ff
and b
ld [hl], a
jr .done
.read
ld b, [hl]
ld a, d
and b
.done
pop bc
pop de
pop hl
ld c, a
ret
; END_INCLUDE \\?\M:\Code\Research\pokered-master\engine\flag_action.asm
; BEGIN_INCLUDE \\?\M:\Code\Research\pokered-master\engine\events\heal_party.asm
HealParty:
; Restore HP and PP.
ld hl, wPartySpecies
ld de, wPartyMon1HP
.healmon
ld a, [hli]
cp $ff
jr z, .done
push hl
push de
ld hl, MON_STATUS - MON_HP
add hl, de
xor a
ld [hl], a
push de
ld b, NUM_MOVES ; A Pok mon has 4 moves
.pp
ld hl, MON_MOVES - MON_HP
add hl, de
ld a, [hl]
and a
jr z, .nextmove
dec a
ld hl, MON_PP - MON_HP
add hl, de
push hl
push de
push bc
ld hl, Moves
ld bc, MOVE_LENGTH
call AddNTimes
ld de, wMoveData
ld a, BANK(Moves)
call FarCopyData
ld a, [wMoveData + MOVE_PP]
pop bc
pop de
pop hl
inc de
push bc
ld b, a
ld a, [hl]
and PP_UP_MASK
add b
ld [hl], a
pop bc
.nextmove
dec b
jr nz, .pp
pop de
ld hl, MON_MAXHP - MON_HP
add hl, de
ld a, [hli]
ld [de], a
inc de
ld a, [hl]
ld [de], a
pop de
pop hl
push hl
ld bc, PARTYMON_STRUCT_LENGTH
ld h, d
ld l, e
add hl, bc
ld d, h
ld e, l
pop hl
jr .healmon
.done
xor a
ld [wWhichPokemon], a
ld [wUsingPPUp], a
ld a, [wPartyCount]
ld b, a
.ppup
push bc
call RestoreBonusPP
pop bc
ld hl, wWhichPokemon
inc [hl]
dec b
jr nz, .ppup
ret
; END_INCLUDE \\?\M:\Code\Research\pokered-master\engine\events\heal_party.asm
; BEGIN_INCLUDE \\?\M:\Code\Research\pokered-master\engine\math\bcd.asm
; divide hMoney by hDivideBCDDivisor
; return output in hDivideBCDQuotient (same as hDivideBCDDivisor)
; used only to halve player money upon losing a fight
DivideBCDPredef::
DivideBCDPredef2::
DivideBCDPredef3:: ; only used function
DivideBCDPredef4::
call GetPredefRegisters
DivideBCD::
xor a
ldh [hDivideBCDBuffer], a
ldh [hDivideBCDBuffer+1], a
ldh [hDivideBCDBuffer+2], a
ld d, $1
.mulBy10Loop
; multiply the divisor by 10 until the leading digit is nonzero
; to set up the standard long division algorithm
ldh a, [hDivideBCDDivisor]
and $f0
jr nz, .next
inc d
ldh a, [hDivideBCDDivisor]
swap a
and $f0
ld b, a
ldh a, [hDivideBCDDivisor+1]
swap a
ldh [hDivideBCDDivisor+1], a
and $f
or b
ldh [hDivideBCDDivisor], a
ldh a, [hDivideBCDDivisor+1]
and $f0
ld b, a
ldh a, [hDivideBCDDivisor+2]
swap a
ldh [hDivideBCDDivisor+2], a
and $f
or b
ldh [hDivideBCDDivisor+1], a
ldh a, [hDivideBCDDivisor+2]
and $f0
ldh [hDivideBCDDivisor+2], a
jr .mulBy10Loop
.next
push de
push de
call DivideBCD_getNextDigit
pop de
ld a, b
swap a
and $f0
ldh [hDivideBCDBuffer], a
dec d
jr z, .next2
push de
call DivideBCD_divDivisorBy10
call DivideBCD_getNextDigit
pop de
ldh a, [hDivideBCDBuffer]
or b
ldh [hDivideBCDBuffer], a
dec d
jr z, .next2
push de
call DivideBCD_divDivisorBy10
call DivideBCD_getNextDigit
pop de
ld a, b
swap a
and $f0
ldh [hDivideBCDBuffer+1], a
dec d
jr z, .next2
push de
call DivideBCD_divDivisorBy10
call DivideBCD_getNextDigit
pop de
ldh a, [hDivideBCDBuffer+1]
or b
ldh [hDivideBCDBuffer+1], a
dec d
jr z, .next2
push de
call DivideBCD_divDivisorBy10
call DivideBCD_getNextDigit
pop de
ld a, b
swap a
and $f0
ldh [hDivideBCDBuffer+2], a
dec d
jr z, .next2
push de
call DivideBCD_divDivisorBy10
call DivideBCD_getNextDigit
pop de
ldh a, [hDivideBCDBuffer+2]
or b
ldh [hDivideBCDBuffer+2], a
.next2
ldh a, [hDivideBCDBuffer]
ldh [hDivideBCDQuotient], a ; the same memory location as hDivideBCDDivisor
ldh a, [hDivideBCDBuffer+1]
ldh [hDivideBCDQuotient+1], a
ldh a, [hDivideBCDBuffer+2]
ldh [hDivideBCDQuotient+2], a
pop de
ld a, $6
sub d
and a
ret z
.divResultBy10loop
push af
call DivideBCD_divDivisorBy10
pop af
dec a
jr nz, .divResultBy10loop
ret
DivideBCD_divDivisorBy10:
ldh a, [hDivideBCDDivisor+2]
swap a
and $f
ld b, a
ldh a, [hDivideBCDDivisor+1]
swap a
ldh [hDivideBCDDivisor+1], a
and $f0
or b
ldh [hDivideBCDDivisor+2], a
ldh a, [hDivideBCDDivisor+1]
and $f
ld b, a
ldh a, [hDivideBCDDivisor]
swap a
ldh [hDivideBCDDivisor], a
and $f0
or b
ldh [hDivideBCDDivisor+1], a
ldh a, [hDivideBCDDivisor]
and $f
ldh [hDivideBCDDivisor], a
ret
DivideBCD_getNextDigit:
ld bc, $3
.loop
ld de, hMoney ; the dividend
ld hl, hDivideBCDDivisor
push bc
call StringCmp
pop bc
ret c
inc b
ld de, hMoney + 2 ; since SubBCD works starting from the least significant digit
ld hl, hDivideBCDDivisor + 2
push bc
call SubBCD
pop bc
jr .loop
AddBCDPredef::
call GetPredefRegisters
AddBCD::
and a
ld b, c
.add
ld a, [de]
adc [hl]
daa
ld [de], a
dec de
dec hl
dec c
jr nz, .add
jr nc, .done
ld a, $99
inc de
.fill
ld [de], a
inc de
dec b
jr nz, .fill
.done
ret
SubBCDPredef::
call GetPredefRegisters
SubBCD::
and a
ld b, c
.sub
ld a, [de]
sbc [hl]
daa
ld [de], a
dec de
dec hl
dec c
jr nz, .sub
jr nc, .done
ld a, $00
inc de
.fill
ld [de], a
inc de
dec b
jr nz, .fill
scf
.done
ret
; END_INCLUDE \\?\M:\Code\Research\pokered-master\engine\math\bcd.asm
