ld a, $ff
ld [wUnusedPlayerDataByte], a
ld hl, wPartyCount
call InitializeEmptyList
ld hl, wBoxCount
call InitializeEmptyList
ld hl, wNumBagItems
call InitializeEmptyList
ld hl, wNumBoxItems
call InitializeEmptyList
DEF START_MONEY EQU $3000
