; BEGIN_INCLUDE \\?\M:\Code\Research\pokered-master\engine\overworld\pathfinding.asm
FindPathToPlayer:
xor a
ld hl, hFindPathNumSteps
ld [hli], a ; hFindPathNumSteps
ld [hli], a ; hFindPathFlags
ld [hli], a ; hFindPathYProgress
ld [hl], a ; hFindPathXProgress
ld hl, wNPCMovementDirections2
ld de, $0
.loop
ldh a, [hFindPathYProgress]
ld b, a
ldh a, [hNPCPlayerYDistance] ; Y distance in steps
call CalcDifference
ld d, a
and a
jr nz, .stillHasYProgress
ldh a, [hFindPathFlags]
set BIT_PATH_FOUND_Y, a
ldh [hFindPathFlags], a
.stillHasYProgress
ldh a, [hFindPathXProgress]
ld b, a
ldh a, [hNPCPlayerXDistance] ; X distance in steps
call CalcDifference
ld e, a
and a
jr nz, .stillHasXProgress
ldh a, [hFindPathFlags]
set BIT_PATH_FOUND_X, a
ldh [hFindPathFlags], a
.stillHasXProgress
ldh a, [hFindPathFlags]
cp (1 << BIT_PATH_FOUND_X) | (1 << BIT_PATH_FOUND_Y)
jr z, .done
; Compare whether the X distance between the player and the current of the path
; is greater or if the Y distance is. Then, try to reduce whichever is greater.
ld a, e
cp d
jr c, .yDistanceGreater
; x distance is greater
ldh a, [hNPCPlayerRelativePosFlags]
bit BIT_PLAYER_LOWER_X, a
jr nz, .playerIsLeftOfNPC
ld d, NPC_MOVEMENT_RIGHT
jr .next1
.playerIsLeftOfNPC
ld d, NPC_MOVEMENT_LEFT
.next1
ldh a, [hFindPathXProgress]
add 1
ldh [hFindPathXProgress], a
jr .storeDirection
.yDistanceGreater
ldh a, [hNPCPlayerRelativePosFlags]
bit BIT_PLAYER_LOWER_Y, a
jr nz, .playerIsAboveNPC
ld d, NPC_MOVEMENT_DOWN
jr .next2
.playerIsAboveNPC
ld d, NPC_MOVEMENT_UP
.next2
ldh a, [hFindPathYProgress]
add 1
ldh [hFindPathYProgress], a
.storeDirection
ld a, d
ld [hli], a
ldh a, [hFindPathNumSteps]
inc a
ldh [hFindPathNumSteps], a
jp .loop
.done
ld [hl], $ff
ret
CalcPositionOfPlayerRelativeToNPC:
xor a
ldh [hNPCPlayerRelativePosFlags], a
ld a, [wSpritePlayerStateData1YPixels]
ld d, a
ld a, [wSpritePlayerStateData1XPixels]
ld e, a
ld hl, wSpriteStateData1
ldh a, [hNPCSpriteOffset]
add l
add SPRITESTATEDATA1_YPIXELS
ld l, a
jr nc, .noCarry
inc h
.noCarry
ld a, d
ld b, a
ld a, [hli] ; NPC sprite screen Y position in pixels
call CalcDifference
jr nc, .NPCSouthOfOrAlignedWithPlayer
; NPC north of player
push hl
ld hl, hNPCPlayerRelativePosFlags
bit BIT_PLAYER_LOWER_Y, [hl]
set BIT_PLAYER_LOWER_Y, [hl]
pop hl
jr .divideYDistance
.NPCSouthOfOrAlignedWithPlayer
push hl
ld hl, hNPCPlayerRelativePosFlags
bit BIT_PLAYER_LOWER_Y, [hl]
res BIT_PLAYER_LOWER_Y, [hl]
pop hl
.divideYDistance
push hl
ld hl, hDividend2
ld [hli], a
ld a, 16
ld [hli], a
call DivideBytes ; divide Y absolute distance by 16
ld a, [hl] ; quotient
ldh [hNPCPlayerYDistance], a
pop hl
inc hl
ld b, e
ld a, [hl] ; NPC sprite screen X position in pixels
call CalcDifference
jr nc, .NPCEastOfOrAlignedWithPlayer
; NPC west of player
push hl
ld hl, hNPCPlayerRelativePosFlags
bit BIT_PLAYER_LOWER_X, [hl]
set BIT_PLAYER_LOWER_X, [hl]
pop hl
jr .divideXDistance
.NPCEastOfOrAlignedWithPlayer
push hl
ld hl, hNPCPlayerRelativePosFlags
bit BIT_PLAYER_LOWER_X, [hl]
res BIT_PLAYER_LOWER_X, [hl]
pop hl
.divideXDistance
ldh [hDividend2], a
ld a, 16
ldh [hDivisor2], a
call DivideBytes ; divide X absolute distance by 16
ldh a, [hQuotient2]
ldh [hNPCPlayerXDistance], a
ldh a, [hNPCPlayerRelativePosPerspective]
and a
ret z
ldh a, [hNPCPlayerRelativePosFlags]
cpl
and $3
ldh [hNPCPlayerRelativePosFlags], a
ret
ConvertNPCMovementDirectionsToJoypadMasks:
ldh a, [hNPCMovementDirections2Index]
ld [wNPCMovementDirections2Index], a
dec a
ld de, wSimulatedJoypadStatesEnd
ld hl, wNPCMovementDirections2
add l
ld l, a
jr nc, .loop
inc h
.loop
ld a, [hld]
call ConvertNPCMovementDirectionToJoypadMask
ld [de], a
inc de
ldh a, [hNPCMovementDirections2Index]
dec a
ldh [hNPCMovementDirections2Index], a
jr nz, .loop
ret
ConvertNPCMovementDirectionToJoypadMask:
push hl
ld b, a
ld hl, NPCMovementDirectionsToJoypadMasksTable
.loop
ld a, [hli]
cp $ff
jr z, .done
cp b
jr z, .loadJoypadMask
inc hl
jr .loop
.loadJoypadMask
ld a, [hl]
.done
pop hl
ret
NPCMovementDirectionsToJoypadMasksTable:
db NPC_MOVEMENT_UP, PAD_UP
db NPC_MOVEMENT_DOWN, PAD_DOWN
db NPC_MOVEMENT_LEFT, PAD_LEFT
db NPC_MOVEMENT_RIGHT, PAD_RIGHT
db $ff
; unreferenced
ret
; END_INCLUDE \\?\M:\Code\Research\pokered-master\engine\overworld\pathfinding.asm
; BEGIN_INCLUDE \\?\M:\Code\Research\pokered-master\engine\gfx\hp_bar.asm
HPBarLength:
call GetPredefRegisters
; calculates bc * 48 / de, the number of pixels the HP bar has
; the result is always at least 1
GetHPBarLength:
push hl
xor a
ld hl, hMultiplicand
ld [hli], a
ld a, b
ld [hli], a
ld a, c
ld [hli], a
ld [hl], $30
call Multiply ; 48 * bc (hp bar is 48 pixels long)
ld a, d
and a
jr z, .maxHPSmaller256
srl d ; make HP in de fit into 1 byte by dividing by 4
rr e
srl d
rr e
ldh a, [hMultiplicand+1]
ld b, a
ldh a, [hMultiplicand+2]
srl b ; divide multiplication result as well
rr a
srl b
rr a
ldh [hMultiplicand+2], a
ld a, b
ldh [hMultiplicand+1], a
.maxHPSmaller256
ld a, e
ldh [hDivisor], a
ld b, $4
call Divide
ldh a, [hMultiplicand+2]
ld e, a ; e = bc * 48 / de (num of pixels of HP bar)
pop hl
and a
ret nz
ld e, $1 ; make result at least 1
ret
; predef $48
UpdateHPBar:
UpdateHPBar2:
push hl
ld hl, wHPBarOldHP
ld a, [hli]
ld c, a ; old HP into bc
ld a, [hli]
ld b, a
ld a, [hli]
ld e, a ; new HP into de
ld d, [hl]
pop hl
push de
push bc
call UpdateHPBar_CalcHPDifference
ld a, e
ld [wHPBarHPDifference+1], a
ld a, d
ld [wHPBarHPDifference], a
pop bc
pop de
call UpdateHPBar_CompareNewHPToOldHP
ret z
ld a, $ff
jr c, .HPdecrease
ld a, $1
.HPdecrease
ld [wHPBarDelta], a
call GetPredefRegisters
ld a, [wHPBarNewHP]
ld e, a
ld a, [wHPBarNewHP+1]
ld d, a
.animateHPBarLoop
push de
ld a, [wHPBarOldHP]
ld c, a
ld a, [wHPBarOldHP+1]
ld b, a
call UpdateHPBar_CompareNewHPToOldHP
jr z, .animateHPBarDone
jr nc, .HPIncrease
; HP decrease
dec bc ; subtract 1 HP
ld a, c
ld [wHPBarNewHP], a
ld a, b
ld [wHPBarNewHP+1], a
call UpdateHPBar_CalcOldNewHPBarPixels
ld a, e
sub d ; calc pixel difference
jr .ok
.HPIncrease
inc bc ; add 1 HP
ld a, c
ld [wHPBarNewHP], a
ld a, b
ld [wHPBarNewHP+1], a
call UpdateHPBar_CalcOldNewHPBarPixels
ld a, d
sub e ; calc pixel difference
.ok
call UpdateHPBar_PrintHPNumber
and a
jr z, .noPixelDifference
call UpdateHPBar_AnimateHPBar
.noPixelDifference
ld a, [wHPBarNewHP]
ld [wHPBarOldHP], a
ld a, [wHPBarNewHP+1]
ld [wHPBarOldHP+1], a
pop de
jr .animateHPBarLoop
.animateHPBarDone
pop de
ld a, e
ld [wHPBarOldHP], a
ld a, d
ld [wHPBarOldHP+1], a
or e
jr z, .monFainted
call UpdateHPBar_CalcOldNewHPBarPixels
ld d, e
.monFainted
call UpdateHPBar_PrintHPNumber
ld a, $1
call UpdateHPBar_AnimateHPBar
jp Delay3
; animates the HP bar going up or down for (a) ticks (two waiting frames each)
; stops prematurely if bar is filled up
; e: current health (in pixels) to start with
UpdateHPBar_AnimateHPBar:
push hl
.barAnimationLoop
push af
push de
ld d, $6
call DrawHPBar
ld c, 2
call DelayFrames
pop de
ld a, [wHPBarDelta] ; +1 or -1
add e
cp $31
jr nc, .barFilledUp
ld e, a
pop af
dec a
jr nz, .barAnimationLoop
pop hl
ret
.barFilledUp
pop af
pop hl
ret
; compares old HP and new HP and sets c and z flags accordingly
UpdateHPBar_CompareNewHPToOldHP:
ld a, d
sub b
ret nz
ld a, e
sub c
ret
; calcs HP difference between bc and de (into de)
UpdateHPBar_CalcHPDifference:
ld a, d
sub b
jr c, .oldHPGreater
jr z, .testLowerByte
.newHPGreater
ld a, e
sub c
ld e, a
ld a, d
sbc b
ld d, a
ret
.oldHPGreater
ld a, c
sub e
ld e, a
ld a, b
sbc d
ld d, a
ret
.testLowerByte
ld a, e
sub c
jr c, .oldHPGreater
jr nz, .newHPGreater
ld de, $0
ret
UpdateHPBar_PrintHPNumber:
push af
push de
ld a, [wHPBarType]
and a
jr z, .done ; don't print number in enemy HUD
; convert from little-endian to big-endian for PrintNumber
ld a, [wHPBarOldHP]
ld [wHPBarTempHP + 1], a
ld a, [wHPBarOldHP + 1]
ld [wHPBarTempHP], a
push hl
ldh a, [hUILayoutFlags]
bit BIT_PARTY_MENU_HP_BAR, a
jr z, .hpBelowBar
ld de, $9
jr .next
.hpBelowBar
ld de, $15
.next
add hl, de
push hl
ld a, ' '
ld [hli], a
ld [hli], a
ld [hli], a
pop hl
ld de, wHPBarTempHP
lb bc, 2, 3
call PrintNumber
call DelayFrame
pop hl
.done
pop de
pop af
ret
; calcs number of HP bar pixels for old and new HP value
; d: new pixels
; e: old pixels
UpdateHPBar_CalcOldNewHPBarPixels:
push hl
ld hl, wHPBarMaxHP
ld a, [hli] ; max HP into de
ld e, a
ld a, [hli]
ld d, a
ld a, [hli] ; old HP into bc
ld c, a
ld a, [hli]
ld b, a
ld a, [hli] ; new HP into hl
ld h, [hl]
ld l, a
push hl
push de
call GetHPBarLength ; calc num pixels for old HP
ld a, e
pop de
pop bc
push af
call GetHPBarLength ; calc num pixels for new HP
pop af
ld d, e
ld e, a
pop hl
ret
; END_INCLUDE \\?\M:\Code\Research\pokered-master\engine\gfx\hp_bar.asm
