cp NUM_MOVES
jr nz, .PrintPP
.PPDone
hlcoord 9, 3
ld de, StatusScreenExpText
call PlaceString
ld a, [wLoadedMonLevel]
push af
cp MAX_LEVEL
jr z, .Level100
inc a
ld [wLoadedMonLevel], a ; Increase temporarily if not 100
.Level100
hlcoord 14, 6
ld [hl], '<to>'
inc hl
inc hl
call PrintLevel
pop af
ld [wLoadedMonLevel], a
ld de, wLoadedMonExp
hlcoord 12, 4
lb bc, 3, 7
call PrintNumber ; exp
call CalcExpToLevelUp
ld de, wLoadedMonExp
hlcoord 7, 6
lb bc, 3, 7
call PrintNumber ; exp needed to level up
; unneeded, this clears the diacritic characters in JPN versions
hlcoord 9, 0
call StatusScreen_ClearName
hlcoord 9, 1
call StatusScreen_ClearName
ld a, [wMonHIndex]
ld [wNamedObjectIndex], a
call GetMonName
hlcoord 9, 1
call PlaceString
ld a, $1
ldh [hAutoBGTransferEnabled], a
call Delay3
call WaitForTextScrollButtonPress
pop af
ldh [hTileAnimations], a
ld hl, wStatusFlags2
res BIT_NO_AUDIO_FADE_OUT, [hl]
ld a, $77
ldh [rAUDVOL], a
call GBPalWhiteOut
jp ClearScreen
CalcExpToLevelUp:
ld a, [wLoadedMonLevel]
cp MAX_LEVEL
jr z, .atMaxLevel
inc a
ld d, a
callfar CalcExperience
ld hl, wLoadedMonExp + 2
ldh a, [hExperience + 2]
sub [hl]
ld [hld], a
ldh a, [hExperience + 1]
sbc [hl]
ld [hld], a
ldh a, [hExperience]
sbc [hl]
ld [hld], a
ret
.atMaxLevel
ld hl, wLoadedMonExp
xor a
ld [hli], a
ld [hli], a
ld [hl], a
ret
StatusScreenExpText:
db "EXP POINTS"
next "LEVEL UP@"
StatusScreen_ClearName:
ld bc, NAME_LENGTH - 1
ld a, ' '
jp FillMemory
StatusScreen_PrintPP:
; print PP or -- c times, going down two rows each time
ld [hli], a
ld [hld], a
add hl, de
dec c
jr nz, StatusScreen_PrintPP
ret
; END_INCLUDE \\?\M:\Code\Research\pokered-master\engine\pokemon\status_screen.asm
