INCLUDE "data/sprites/sprites.asm"
; END_INCLUDE \\?\M:\Code\Research\pokered-master\engine\overworld\map_sprites.asm
; BEGIN_INCLUDE \\?\M:\Code\Research\pokered-master\engine\overworld\emotion_bubbles.asm
EmotionBubble:
ld a, [wWhichEmotionBubble]
ld c, a
ld b, 0
ld hl, EmotionBubblesPointerTable
add hl, bc
add hl, bc
ld e, [hl]
inc hl
ld d, [hl]
ld hl, vChars1 tile $78
lb bc, BANK(EmotionBubbles), 4
call CopyVideoData
ld a, [wUpdateSpritesEnabled]
push af
ld a, $ff
ld [wUpdateSpritesEnabled], a
ld a, [wMovementFlags]
bit BIT_LEDGE_OR_FISHING, a ; are the last 4 OAM entries reserved for a shadow or fishing rod?
ld hl, wShadowOAMSprite35Attributes
ld de, wShadowOAMSprite39Attributes
jr z, .next
ld hl, wShadowOAMSprite31Attributes
ld de, wShadowOAMSprite35Attributes
; Copy OAM data 16 bytes forward to make room for emotion bubble OAM data at the
; start of the OAM buffer.
.next
ld bc, $90
.loop
ld a, [hl]
ld [de], a
dec hl
dec de
dec bc
ld a, c
or b
jr nz, .loop
; get the screen coordinates of the sprite the bubble is to be displayed above
ld hl, wSpritePlayerStateData1YPixels
ld a, [wEmotionBubbleSpriteIndex]
swap a
ld c, a
ld b, 0
add hl, bc
ld a, [hli]
ld b, a
inc hl
ld a, [hl]
add $8
ld c, a
ld de, EmotionBubblesOAMBlock
xor a
call WriteOAMBlock
ld c, 60
call DelayFrames
pop af
ld [wUpdateSpritesEnabled], a
call DelayFrame
jp UpdateSprites
EmotionBubblesPointerTable:
; entries correspond to *_BUBBLE constants
dw ShockEmote
dw QuestionEmote
dw HappyEmote
EmotionBubblesOAMBlock:
; tile ID, attributes
db $f8, 0
db $f9, 0
db $fa, 0
db $fb, 0
EmotionBubbles:
ShockEmote: INCBIN "gfx/emotes/shock.2bpp"
QuestionEmote: INCBIN "gfx/emotes/question.2bpp"
HappyEmote: INCBIN "gfx/emotes/happy.2bpp"
; END_INCLUDE \\?\M:\Code\Research\pokered-master\engine\overworld\emotion_bubbles.asm
; BEGIN_INCLUDE \\?\M:\Code\Research\pokered-master\engine\events\evolve_trade.asm
InGameTrade_CheckForTradeEvo:
; In Japanese Blue, TradeMons include a Graveler and a Haunter,
; both of which have Japanese names that start with " ",
; which is what this routine originally checked in that game.
; For English Red and Blue, this routine was adjusted for
; Graveler's English name and Haunter's early English name "Spectre".
; The final release replaced Graveler and Haunter in TradeMons.
ld a, [wInGameTradeReceiveMonName]
cp 'G' ; GRAVELER
jr z, .nameMatched
; "SPECTRE" (HAUNTER)
cp 'S'
ret nz
ld a, [wInGameTradeReceiveMonName + 1]
cp 'P'
ret nz
.nameMatched
ld a, [wPartyCount]
dec a
ld [wWhichPokemon], a
ld a, TRUE
ld [wForceEvolution], a
ld a, LINK_STATE_TRADING
ld [wLinkState], a
callfar TryEvolvingMon
xor a ; LINK_STATE_NONE
ld [wLinkState], a
jp PlayDefaultMusic
; END_INCLUDE \\?\M:\Code\Research\pokered-master\engine\events\evolve_trade.asm
; BEGIN_INCLUDE \\?\M:\Code\Research\pokered-master\engine\battle\move_effects\substitute.asm
SubstituteEffect_:
ld c, 50
call DelayFrames
ld hl, wBattleMonMaxHP
ld de, wPlayerSubstituteHP
ld bc, wPlayerBattleStatus2
ldh a, [hWhoseTurn]
and a
jr z, .notEnemy
ld hl, wEnemyMonMaxHP
ld de, wEnemySubstituteHP
ld bc, wEnemyBattleStatus2
.notEnemy
ld a, [bc]
bit HAS_SUBSTITUTE_UP, a ; user already has substitute?
jr nz, .alreadyHasSubstitute
; quarter health to remove from user
; assumes max HP is 1023 or lower
push bc
ld a, [hli]
ld b, [hl]
srl a
rr b
srl a
rr b ; max hp / 4
push de
ld de, wBattleMonHP - wBattleMonMaxHP
add hl, de ; point hl to current HP low byte
pop de
ld a, b
ld [de], a ; save copy of HP to subtract in wPlayerSubstituteHP/wEnemySubstituteHP
ld a, [hld]
; subtract [max hp / 4] to current HP
sub b
ld d, a
ld a, [hl]
sbc 0
pop bc
jr c, .notEnoughHP ; underflow means user would be left with negative health
; bug: since it only branches on carry, it will possibly leave user with 0 HP
; user has 0 or more HP
ld [hli], a ; save resulting HP after subtraction into current HP
ld [hl], d
ld h, b
ld l, c
set HAS_SUBSTITUTE_UP, [hl]
ld a, [wOptions]
bit BIT_BATTLE_ANIMATION, a
ld hl, PlayCurrentMoveAnimation
ld b, BANK(PlayCurrentMoveAnimation)
jr z, .animationEnabled
ld hl, AnimationSubstitute
ld b, BANK(AnimationSubstitute)
.animationEnabled
call Bankswitch ; jump to routine depending on animation setting
ld hl, SubstituteText
call PrintText
jpfar DrawHUDsAndHPBars
.alreadyHasSubstitute
ld hl, HasSubstituteText
jr .printText
.notEnoughHP
ld hl, TooWeakSubstituteText
.printText
jp PrintText
SubstituteText:
text_far _SubstituteText
text_end
HasSubstituteText:
text_far _HasSubstituteText
text_end
TooWeakSubstituteText:
text_far _TooWeakSubstituteText
text_end
; END_INCLUDE \\?\M:\Code\Research\pokered-master\engine\battle\move_effects\substitute.asm
; BEGIN_INCLUDE \\?\M:\Code\Research\pokered-master\engine\menus\pc.asm
ActivatePC::
call SaveScreenTilesToBuffer2
ld a, SFX_TURN_ON_PC
call PlaySound
ld hl, TurnedOnPC1Text
call PrintText
call WaitForSoundToFinish
ld hl, wMiscFlags
set BIT_USING_GENERIC_PC, [hl]
call LoadScreenTilesFromBuffer2
call Delay3
PCMainMenu:
farcall DisplayPCMainMenu
ld hl, wMiscFlags
set BIT_NO_MENU_BUTTON_SOUND, [hl]
call HandleMenuInput
bit B_PAD_B, a
jp nz, LogOff
ld a, [wMaxMenuItem]
cp 2
jr nz, .next ;if not 2 menu items (not counting log off) (2 occurs before you get the pokedex)
ld a, [wCurrentMenuItem]
and a
jp z, BillsPC ;if current menu item id is 0, it's bills pc
cp 1
jr z, .playersPC ;if current menu item id is 1, it's players pc
jp LogOff ;otherwise, it's 2, and you're logging off
.next
cp 3
jr nz, .next2 ;if not 3 menu items (not counting log off) (3 occurs after you get the pokedex, before you beat the pokemon league)
ld a, [wCurrentMenuItem]
and a
jp z, BillsPC ;if current menu item id is 0, it's bills pc
cp 1
jr z, .playersPC ;if current menu item id is 1, it's players pc
cp 2
jp z, OaksPC ;if current menu item id is 2, it's oaks pc
jp LogOff ;otherwise, it's 3, and you're logging off
.next2
ld a, [wCurrentMenuItem]
and a
jp z, BillsPC ;if current menu item id is 0, it's bills pc
cp 1
jr z, .playersPC ;if current menu item id is 1, it's players pc
cp 2
jp z, OaksPC ;if current menu item id is 2, it's oaks pc
cp 3
jp z, PKMNLeague ;if current menu item id is 3, it's pkmnleague
jp LogOff ;otherwise, it's 4, and you're logging off
.playersPC
ld hl, wMiscFlags
res BIT_NO_MENU_BUTTON_SOUND, [hl]
set BIT_USING_GENERIC_PC, [hl]
ld a, SFX_ENTER_PC
call PlaySound
call WaitForSoundToFinish
ld hl, AccessedMyPCText
call PrintText
farcall PlayerPC
jr ReloadMainMenu
OaksPC:
ld a, SFX_ENTER_PC
call PlaySound
call WaitForSoundToFinish
farcall OpenOaksPC
jr ReloadMainMenu
PKMNLeague:
ld a, SFX_ENTER_PC
call PlaySound
call WaitForSoundToFinish
farcall PKMNLeaguePC
jr ReloadMainMenu
BillsPC:
ld a, SFX_ENTER_PC
call PlaySound
call WaitForSoundToFinish
CheckEvent EVENT_MET_BILL
jr nz, .billsPC ;if you've met bill, use that bill's instead of someone's
ld hl, AccessedSomeonesPCText
jr .printText
.billsPC
ld hl, AccessedBillsPCText
.printText
call PrintText
farcall BillsPC_
ReloadMainMenu:
xor a
ld [wDoNotWaitForButtonPressAfterDisplayingText], a
call ReloadMapData
call UpdateSprites
jp PCMainMenu
LogOff:
ld a, SFX_TURN_OFF_PC
call PlaySound
call WaitForSoundToFinish
ld hl, wMiscFlags
res BIT_USING_GENERIC_PC, [hl]
res BIT_NO_MENU_BUTTON_SOUND, [hl]
ret
TurnedOnPC1Text:
text_far _TurnedOnPC1Text
text_end
AccessedBillsPCText:
text_far _AccessedBillsPCText
text_end
AccessedSomeonesPCText:
text_far _AccessedSomeonesPCText
text_end
AccessedMyPCText:
text_far _AccessedMyPCText
text_end
; removes one of the specified item ID [hItemToRemoveID] from bag (if existent)
RemoveItemByID::
ld hl, wBagItems
ldh a, [hItemToRemoveID]
ld b, a
xor a
ldh [hItemToRemoveIndex], a
.loop
ld a, [hli]
cp -1 ; reached terminator?
ret z
cp b
jr z, .foundItem
inc hl
ldh a, [hItemToRemoveIndex]
inc a
ldh [hItemToRemoveIndex], a
jr .loop
.foundItem
ld a, $1
ld [wItemQuantity], a
ldh a, [hItemToRemoveIndex]
ld [wWhichPokemon], a
ld hl, wNumBagItems
jp RemoveItemFromInventory
; END_INCLUDE \\?\M:\Code\Research\pokered-master\engine\menus\pc.asm
SECTION "Play Time", ROMX
; BEGIN_INCLUDE \\?\M:\Code\Research\pokered-master\engine\play_time.asm
TrackPlayTime::
call CountDownIgnoreInputBitReset
ld a, [wStatusFlags6]
bit BIT_GAME_TIMER_COUNTING, a
ret z
ld a, [wPlayTimeMaxed]
and a
ret nz
ld a, [wPlayTimeFrames]
inc a
ld [wPlayTimeFrames], a
cp 60
ret nz
xor a
ld [wPlayTimeFrames], a
ld a, [wPlayTimeSeconds]
inc a
ld [wPlayTimeSeconds], a
cp 60
ret nz
xor a
ld [wPlayTimeSeconds], a
ld a, [wPlayTimeMinutes]
inc a
ld [wPlayTimeMinutes], a
cp 60
ret nz
xor a
ld [wPlayTimeMinutes], a
ld a, [wPlayTimeHours]
inc a
ld [wPlayTimeHours], a
cp $ff
ret nz
ld a, $ff
ld [wPlayTimeMaxed], a
ret
CountDownIgnoreInputBitReset:
ld a, [wIgnoreInputCounter]
and a
jr nz, .decrement
ld a, $ff
jr .continue
.decrement
dec a
.continue
ld [wIgnoreInputCounter], a
and a
ret nz
ld a, [wStatusFlags5]
res BIT_UNKNOWN_5_1, a
res BIT_UNKNOWN_5_2, a
bit BIT_DISABLE_JOYPAD, a
res BIT_DISABLE_JOYPAD, a
ld [wStatusFlags5], a
ret z
xor a
ldh [hJoyPressed], a
ldh [hJoyHeld], a
