SECTION "Battle Engine 3", ROMX
; BEGIN_INCLUDE \\?\M:\Code\Research\pokered-master\engine\battle\print_type.asm
; [wCurSpecies] = pokemon ID
; hl = dest addr
PrintMonType:
call GetPredefRegisters
push hl
call GetMonHeader
pop hl
push hl
ld a, [wMonHType1]
call PrintType
ld a, [wMonHType1]
ld b, a
ld a, [wMonHType2]
cp b
pop hl
jr z, EraseType2Text
ld bc, SCREEN_WIDTH * 2
add hl, bc
; a = type
; hl = dest addr
PrintType:
push hl
jr PrintType_
; erase "TYPE2/" if the mon only has 1 type
EraseType2Text:
ld a, ' '
ld bc, $13
add hl, bc
ld bc, $6
jp FillMemory
PrintMoveType:
call GetPredefRegisters
push hl
ld a, [wPlayerMoveType]
; fall through
PrintType_:
add a
ld hl, TypeNames
ld e, a
