; BEGIN_INCLUDE \\?\M:\Code\Research\pokered-master\engine\events\pewter_guys.asm
PewterGuys:
ld hl, wSimulatedJoypadStatesEnd
ld a, [wSimulatedJoypadStatesIndex]
dec a ; this decrement causes it to overwrite the last byte before $FF in the list
ld [wSimulatedJoypadStatesIndex], a
ld d, 0
ld e, a
add hl, de
ld d, h
ld e, l
ld hl, PewterGuysCoordsTable
ld a, [wWhichPewterGuy]
add a
ld b, 0
ld c, a
add hl, bc
ld a, [hli]
ld h, [hl]
ld l, a
ld a, [wYCoord]
ld b, a
ld a, [wXCoord]
ld c, a
.findMatchingCoordsLoop
ld a, [hli]
cp b
jr nz, .nextEntry1
ld a, [hli]
cp c
jr nz, .nextEntry2
ld a, [hli]
ld h, [hl]
ld l, a
.copyMovementDataLoop
ld a, [hli]
cp $ff
ret z
ld [de], a
inc de
ld a, [wSimulatedJoypadStatesIndex]
inc a
ld [wSimulatedJoypadStatesIndex], a
jr .copyMovementDataLoop
.nextEntry1
inc hl
.nextEntry2
inc hl
inc hl
jr .findMatchingCoordsLoop
PewterGuysCoordsTable:
dw PewterMuseumGuyCoords
dw PewterGymGuyCoords
; these are the four coordinates of the spaces below, above, to the left and
; to the right of the museum guy, and pointers to different movements for
; the player to make to get positioned before the main movement.
PewterMuseumGuyCoords:
db 18, 27
dw .down
db 16, 27
dw .up
db 17, 26
dw .left
db 17, 28
dw .right
.down
db PAD_UP, PAD_UP, $ff
.up
db PAD_RIGHT, PAD_LEFT, $ff
.left
db PAD_UP, PAD_RIGHT, $ff
.right
db PAD_UP, PAD_LEFT, $ff
; these are the five coordinates which trigger the gym guy and pointers to
; different movements for the player to make to get positioned before the
; main movement
; $00 is a pause
PewterGymGuyCoords:
db 16, 34
dw .one
db 17, 35
dw .two
db 18, 37
dw .three
db 19, 37
dw .four
db 17, 36
dw .five
.one
db PAD_LEFT, PAD_DOWN, PAD_DOWN, PAD_RIGHT, $ff
.two
db PAD_LEFT, PAD_DOWN, PAD_RIGHT, PAD_LEFT, $ff
.three
db PAD_LEFT, PAD_LEFT, PAD_LEFT, $00, $00, $00, $00, $00, $00, $00, $00, $ff
.four
db PAD_LEFT, PAD_LEFT, PAD_UP, PAD_LEFT, $ff
.five
db PAD_LEFT, PAD_DOWN, PAD_LEFT, $00, $00, $00, $00, $00, $00, $00, $00, $ff
; END_INCLUDE \\?\M:\Code\Research\pokered-master\engine\events\pewter_guys.asm
; BEGIN_INCLUDE \\?\M:\Code\Research\pokered-master\engine\math\multiply_divide.asm
_Multiply::
ld a, $8
ld b, a
xor a
ldh [hProduct], a
ldh [hMultiplyBuffer], a
ldh [hMultiplyBuffer+1], a
ldh [hMultiplyBuffer+2], a
ldh [hMultiplyBuffer+3], a
.loop
ldh a, [hMultiplier]
srl a
ldh [hMultiplier], a ; (aliases: hDivisor, hMultiplier, hPowerOf10)
jr nc, .smallMultiplier
ldh a, [hMultiplyBuffer+3]
ld c, a
ldh a, [hMultiplicand+2]
add c
ldh [hMultiplyBuffer+3], a
ldh a, [hMultiplyBuffer+2]
ld c, a
ldh a, [hMultiplicand+1]
adc c
ldh [hMultiplyBuffer+2], a
ldh a, [hMultiplyBuffer+1]
ld c, a
ldh a, [hMultiplicand] ; (aliases: hMultiplicand)
adc c
ldh [hMultiplyBuffer+1], a
ldh a, [hMultiplyBuffer]
ld c, a
ldh a, [hProduct] ; (aliases: hProduct, hPastLeadingZeros, hQuotient)
adc c
ldh [hMultiplyBuffer], a
.smallMultiplier
dec b
jr z, .done
ldh a, [hMultiplicand+2]
sla a
ldh [hMultiplicand+2], a
ldh a, [hMultiplicand+1]
rl a
ldh [hMultiplicand+1], a
ldh a, [hMultiplicand]
rl a
ldh [hMultiplicand], a
ldh a, [hProduct]
rl a
ldh [hProduct], a
jr .loop
.done
ldh a, [hMultiplyBuffer+3]
ldh [hProduct+3], a
ldh a, [hMultiplyBuffer+2]
ldh [hProduct+2], a
ldh a, [hMultiplyBuffer+1]
ldh [hProduct+1], a
ldh a, [hMultiplyBuffer]
ldh [hProduct], a
ret
_Divide::
xor a
ldh [hDivideBuffer], a
ldh [hDivideBuffer+1], a
ldh [hDivideBuffer+2], a
ldh [hDivideBuffer+3], a
ldh [hDivideBuffer+4], a
ld a, $9
ld e, a
.loop
ldh a, [hDivideBuffer]
ld c, a
ldh a, [hDividend+1] ; (aliases: hMultiplicand)
sub c
ld d, a
ldh a, [hDivisor] ; (aliases: hDivisor, hMultiplier, hPowerOf10)
ld c, a
ldh a, [hDividend] ; (aliases: hProduct, hPastLeadingZeros, hQuotient)
sbc c
jr c, .next
ldh [hDividend], a ; (aliases: hProduct, hPastLeadingZeros, hQuotient)
ld a, d
ldh [hDividend+1], a ; (aliases: hMultiplicand)
ldh a, [hDivideBuffer+4]
inc a
ldh [hDivideBuffer+4], a
jr .loop
.next
ld a, b
cp $1
jr z, .done
ldh a, [hDivideBuffer+4]
sla a
ldh [hDivideBuffer+4], a
ldh a, [hDivideBuffer+3]
rl a
ldh [hDivideBuffer+3], a
ldh a, [hDivideBuffer+2]
rl a
ldh [hDivideBuffer+2], a
ldh a, [hDivideBuffer+1]
rl a
ldh [hDivideBuffer+1], a
dec e
jr nz, .next2
ld a, $8
ld e, a
ldh a, [hDivideBuffer]
ldh [hDivisor], a ; (aliases: hDivisor, hMultiplier, hPowerOf10)
xor a
ldh [hDivideBuffer], a
ldh a, [hDividend+1] ; (aliases: hMultiplicand)
ldh [hDividend], a ; (aliases: hProduct, hPastLeadingZeros, hQuotient)
ldh a, [hDividend+2]
ldh [hDividend+1], a ; (aliases: hMultiplicand)
ldh a, [hDividend+3]
ldh [hDividend+2], a
.next2
ld a, e
cp $1
jr nz, .okay
dec b
.okay
ldh a, [hDivisor] ; (aliases: hDivisor, hMultiplier, hPowerOf10)
srl a
ldh [hDivisor], a ; (aliases: hDivisor, hMultiplier, hPowerOf10)
ldh a, [hDivideBuffer]
rr a
ldh [hDivideBuffer], a
jr .loop
.done
ldh a, [hDividend+1] ; (aliases: hMultiplicand)
ldh [hRemainder], a ; (aliases: hDivisor, hMultiplier, hPowerOf10)
ldh a, [hDivideBuffer+4]
ldh [hQuotient+3], a
ldh a, [hDivideBuffer+3]
ldh [hQuotient+2], a
ldh a, [hDivideBuffer+2]
ldh [hQuotient+1], a ; (aliases: hMultiplicand)
ldh a, [hDivideBuffer+1]
ldh [hDividend], a ; (aliases: hProduct, hPastLeadingZeros, hQuotient)
ret
; END_INCLUDE \\?\M:\Code\Research\pokered-master\engine\math\multiply_divide.asm
