; BEGIN_INCLUDE \\?\M:\Code\Research\pokered-master\engine\overworld\hidden_events.asm
IsPlayerOnDungeonWarp::
xor a
ld [wWhichDungeonWarp], a
ld a, [wStatusFlags3]
bit BIT_ON_DUNGEON_WARP, a
ret nz
call ArePlayerCoordsInArray
ret nc
ld a, [wCoordIndex]
ld [wWhichDungeonWarp], a
ld hl, wStatusFlags3
set BIT_ON_DUNGEON_WARP, [hl]
ld hl, wStatusFlags6
set BIT_DUNGEON_WARP, [hl]
ret
; if a hidden event was found, stores $00 in [hDidntFindAnyHiddenEvent], else stores $ff
CheckForHiddenEvent::
ld hl, hItemAlreadyFound
xor a
ld [hli], a ; [hItemAlreadyFound]
ld [hli], a ; [hSavedMapTextPtr]
ld [hli], a ; [hSavedMapTextPtr + 1]
ld [hl], a ; [hDidntFindAnyHiddenEvent]
ld de, $0
ld hl, HiddenEventMaps
.hiddenMapLoop
ld a, [hli]
ld b, a
cp $ff
jr z, .noMatch
ld a, [wCurMap]
cp b
jr z, .foundMatchingMap
inc de
inc de
jr .hiddenMapLoop
.foundMatchingMap
ld hl, HiddenEventPointers
add hl, de
ld a, [hli]
ld h, [hl]
ld l, a
push hl
ld hl, wHiddenEventFunctionArgument
xor a
ld [hli], a
ld [hli], a
ld [hl], a
pop hl
.hiddenEventLoop
ld a, [hli]
cp $ff
jr z, .noMatch
ld [wHiddenEventY], a
ld b, a
ld a, [hli]
ld [wHiddenEventX], a
ld c, a
call CheckIfCoordsInFrontOfPlayerMatch
ldh a, [hCoordsInFrontOfPlayerMatch]
and a
jr z, .foundMatchingEvent
inc hl
inc hl
inc hl
inc hl
push hl
ld hl, wHiddenEventIndex
inc [hl]
pop hl
jr .hiddenEventLoop
.foundMatchingEvent
ld a, [hli]
ld [wHiddenEventFunctionArgument], a
ld a, [hli]
ld [wHiddenEventFunctionRomBank], a
ld a, [hli]
ld h, [hl]
ld l, a
ret
.noMatch
ld a, $ff
ldh [hDidntFindAnyHiddenEvent], a
ret
; checks if the coordinates in front of the player's sprite match Y in b and X in c
; [hCoordsInFrontOfPlayerMatch] = $00 if they match, $ff if they don't match
CheckIfCoordsInFrontOfPlayerMatch:
ld a, [wSpritePlayerStateData1FacingDirection]
cp SPRITE_FACING_UP
jr z, .facingUp
cp SPRITE_FACING_LEFT
jr z, .facingLeft
cp SPRITE_FACING_RIGHT
jr z, .facingRight
; facing down
ld a, [wYCoord]
inc a
jr .upDownCommon
.facingUp
ld a, [wYCoord]
dec a
.upDownCommon
cp b
jr nz, .didNotMatch
ld a, [wXCoord]
cp c
jr nz, .didNotMatch
jr .matched
.facingLeft
ld a, [wXCoord]
dec a
jr .leftRightCommon
.facingRight
ld a, [wXCoord]
inc a
.leftRightCommon
cp c
jr nz, .didNotMatch
ld a, [wYCoord]
cp b
jr nz, .didNotMatch
.matched
xor a
jr .done
.didNotMatch
ld a, $ff
.done
ldh [hCoordsInFrontOfPlayerMatch], a
ret
INCLUDE "data/events/hidden_events.asm"
; END_INCLUDE \\?\M:\Code\Research\pokered-master\engine\overworld\hidden_events.asm
SECTION "Screen Effects", ROMX
; BEGIN_INCLUDE \\?\M:\Code\Research\pokered-master\engine\gfx\screen_effects.asm
; b = new color for BG color 0 (usually white) for 4 frames
ChangeBGPalColor0_4Frames:
call GetPredefRegisters
ldh a, [rBGP]
or b
ldh [rBGP], a
ld c, 4
call DelayFrames
ldh a, [rBGP]
and %11111100
ldh [rBGP], a
ret
PredefShakeScreenVertically:
; Moves the window down and then back in a sequence of progressively smaller
; numbers of pixels, starting at b.
call GetPredefRegisters
ld a, 1
ld [wDisableVBlankWYUpdate], a
xor a
.loop
ldh [hMutateWY], a
call .MutateWY
call .MutateWY
dec b
ld a, b
jr nz, .loop
xor a
ld [wDisableVBlankWYUpdate], a
ret
.MutateWY
ldh a, [hMutateWY]
xor b
ldh [hMutateWY], a
ldh [rWY], a
ld c, 3
jp DelayFrames
PredefShakeScreenHorizontally:
; Moves the window right and then back in a sequence of progressively smaller
; numbers of pixels, starting at b.
call GetPredefRegisters
xor a
.loop
ldh [hMutateWX], a
call .MutateWX
ld c, 1
call DelayFrames
call .MutateWX
dec b
ld a, b
jr nz, .loop
; restore normal WX
ld a, 7
ldh [rWX], a
ret
.MutateWX
ldh a, [hMutateWX]
xor b
ldh [hMutateWX], a
bit 7, a ; negative?
jr z, .skipZeroing
xor a ; zero a if it's negative
.skipZeroing
add 7
ldh [rWX], a
ld c, 4
jp DelayFrames
; END_INCLUDE \\?\M:\Code\Research\pokered-master\engine\gfx\screen_effects.asm
SECTION "Predefs", ROMX
; BEGIN_INCLUDE \\?\M:\Code\Research\pokered-master\engine\events\give_pokemon.asm
_GivePokemon::
; returns success in carry
; and whether the mon was added to the party in [wAddedToParty]
call EnableAutoTextBoxDrawing
xor a
ld [wAddedToParty], a
ld a, [wPartyCount]
cp PARTY_LENGTH
jr c, .addToParty
ld a, [wBoxCount]
cp MONS_PER_BOX
jr nc, .boxFull
; add to box
xor a
ld [wEnemyBattleStatus3], a
ld a, [wCurPartySpecies]
ld [wEnemyMonSpecies2], a
callfar LoadEnemyMonData
call SetPokedexOwnedFlag
callfar SendNewMonToBox
ld hl, wStringBuffer
ld a, [wCurrentBoxNum]
and BOX_NUM_MASK
cp 9
jr c, .singleDigitBoxNum
sub 9
ld [hl], '1'
inc hl
add '0'
jr .next
.singleDigitBoxNum
add '1'
.next
ld [hli], a
ld [hl], '@'
ld hl, SentToBoxText
call PrintText
scf
ret
.boxFull
ld hl, BoxIsFullText
call PrintText
and a
ret
.addToParty
call SetPokedexOwnedFlag
call AddPartyMon
ld a, 1
ld [wDoNotWaitForButtonPressAfterDisplayingText], a
ld [wAddedToParty], a
scf
ret
SetPokedexOwnedFlag:
ld a, [wCurPartySpecies]
push af
ld [wPokedexNum], a
predef IndexToPokedex
ld a, [wPokedexNum]
dec a
ld c, a
ld hl, wPokedexOwned
ld b, FLAG_SET
predef FlagActionPredef
pop af
ld [wNamedObjectIndex], a
call GetMonName
ld hl, GotMonText
jp PrintText
GotMonText:
text_far _GotMonText
sound_get_item_1
text_end
SentToBoxText:
text_far _SentToBoxText
text_end
BoxIsFullText:
text_far _BoxIsFullText
text_end
; END_INCLUDE \\?\M:\Code\Research\pokered-master\engine\events\give_pokemon.asm
; BEGIN_INCLUDE \\?\M:\Code\Research\pokered-master\engine\predefs.asm
GetPredefPointer::
; Back up the contents of the registers (hl, de, bc).
; Then put the bank and address of predef
; wPredefID in [wPredefBank] and hl.
ld a, h
ld [wPredefHL], a
ld a, l
ld [wPredefHL + 1], a
ld hl, wPredefDE
ld a, d
ld [hli], a
ld a, e
ld [hli], a
ASSERT wPredefDE + 2 == wPredefBC
ld a, b
ld [hli], a
ld [hl], c
ld hl, PredefPointers
ld de, 0
ld a, [wPredefID]
ld e, a
add a
add e
ld e, a
jr nc, .nocarry
inc d
.nocarry
add hl, de
ld d, h
ld e, l
; get bank of predef routine
ld a, [de]
ld [wPredefBank], a
; get pointer
inc de
ld a, [de]
ld l, a
inc de
ld a, [de]
ld h, a
ret
INCLUDE "data/predef_pointers.asm"
