; BEGIN_INCLUDE \\?\M:\Code\Research\pokered-master\engine\items\town_map.asm
DEF NOT_VISITED EQU $fe
DEF BIRD_BASE_TILE EQU $04
DisplayTownMap:
call LoadTownMap
ld hl, wUpdateSpritesEnabled
ld a, [hl]
push af
ld [hl], $ff
push hl
ld a, $1
ldh [hJoy7], a
ld a, [wCurMap]
push af
ld b, $0
call DrawPlayerOrBirdSprite
hlcoord 1, 0
ld de, wNameBuffer
call PlaceString
ld hl, wShadowOAMSprite00
ld de, wShadowOAMBackupSprite00
ld bc, OBJ_SIZE * 4
call CopyData
ld hl, vSprites tile BIRD_BASE_TILE
ld de, TownMapCursor
lb bc, BANK(TownMapCursor), (TownMapCursorEnd - TownMapCursor) / TILE_1BPP_SIZE
call CopyVideoDataDouble
xor a
ld [wWhichTownMapLocation], a
pop af
jr .enterLoop
.townMapLoop
hlcoord 0, 0
lb bc, 1, 20
call ClearScreenArea
ld hl, TownMapOrder
ld a, [wWhichTownMapLocation]
ld c, a
ld b, 0
add hl, bc
ld a, [hl]
.enterLoop
ld de, wTownMapCoords
call LoadTownMapEntry
ld a, [de]
push hl
call TownMapCoordsToOAMCoords
ld a, $4
ld [wOAMBaseTile], a
ld hl, wShadowOAMSprite04
call WriteTownMapSpriteOAM ; town map cursor sprite
pop hl
ld de, wNameBuffer
.copyMapName
ld a, [hli]
ld [de], a
inc de
cp '@'
jr nz, .copyMapName
hlcoord 1, 0
ld de, wNameBuffer
call PlaceString
ld hl, wShadowOAMSprite04
ld de, wShadowOAMBackupSprite04
ld bc, OBJ_SIZE * 4
call CopyData
.inputLoop
call TownMapSpriteBlinkingAnimation
call JoypadLowSensitivity
ldh a, [hJoy5]
ld b, a
and PAD_A | PAD_B | PAD_UP | PAD_DOWN
jr z, .inputLoop
ld a, SFX_TINK
call PlaySound
bit B_PAD_UP, b
jr nz, .pressedUp
bit B_PAD_DOWN, b
jr nz, .pressedDown
xor a
ld [wTownMapSpriteBlinkingEnabled], a
ldh [hJoy7], a
ld [wAnimCounter], a
call ExitTownMap
pop hl
pop af
ld [hl], a
ret
.pressedUp
ld a, [wWhichTownMapLocation]
inc a
cp TownMapOrderEnd - TownMapOrder ; number of list items + 1
jr nz, .noOverflow
xor a
.noOverflow
ld [wWhichTownMapLocation], a
jp .townMapLoop
.pressedDown
ld a, [wWhichTownMapLocation]
dec a
cp -1
jr nz, .noUnderflow
ld a, TownMapOrderEnd - TownMapOrder - 1 ; number of list items
.noUnderflow
ld [wWhichTownMapLocation], a
jp .townMapLoop
