TownMapCursorEnd:
LoadTownMap_Nest:
call LoadTownMap
ld hl, wUpdateSpritesEnabled
ld a, [hl]
push af
ld [hl], $ff
push hl
call DisplayWildLocations
call GetMonName
hlcoord 1, 0
call PlaceString
ld h, b
ld l, c
ld de, MonsNestText
call PlaceString
call WaitForTextScrollButtonPress
call ExitTownMap
pop hl
pop af
ld [hl], a
ret
