_RunPaletteCommand:
call GetPredefRegisters
ld a, b
cp SET_PAL_DEFAULT
jr nz, .not_default
ld a, [wDefaultPaletteCommand]
.not_default
cp SET_PAL_PARTY_MENU_HP_BARS
jp z, UpdatePartyMenuBlkPacket
ld l, a
ld h, 0
add hl, hl
ld de, SetPalFunctions
add hl, de
ld a, [hli]
ld h, [hl]
ld l, a
ld de, SendSGBPackets
push de
jp hl
SetPal_BattleBlack:
ld hl, PalPacket_Black
ld de, BlkPacket_Battle
ret
; uses PalPacket_Empty to build a packet based on mon IDs and health color
SetPal_Battle:
ld hl, PalPacket_Empty
ld de, wPalPacket
ld bc, $10
call CopyData
ld a, [wPlayerBattleStatus3]
ld hl, wBattleMonSpecies
call DeterminePaletteID
ld b, a
ld a, [wEnemyBattleStatus3]
ld hl, wEnemyMonSpecies2
call DeterminePaletteID
ld c, a
ld hl, wPalPacket + 1
ld a, [wPlayerHPBarColor]
add PAL_GREENBAR
ld [hli], a
inc hl
ld a, [wEnemyHPBarColor]
add PAL_GREENBAR
ld [hli], a
inc hl
ld a, b
ld [hli], a
inc hl
ld a, c
ld [hl], a
ld hl, wPalPacket
ld de, BlkPacket_Battle
ld a, SET_PAL_BATTLE
ld [wDefaultPaletteCommand], a
ret
SetPal_TownMap:
ld hl, PalPacket_TownMap
ld de, BlkPacket_WholeScreen
ret
; uses PalPacket_Empty to build a packet based the mon ID
SetPal_StatusScreen:
ld hl, PalPacket_Empty
ld de, wPalPacket
ld bc, $10
call CopyData
ld a, [wCurPartySpecies]
cp NUM_POKEMON_INDEXES + 1
jr c, .pokemon
ld a, $1 ; not pokemon
.pokemon
call DeterminePaletteIDOutOfBattle
push af
ld hl, wPalPacket + 1
ld a, [wStatusScreenHPBarColor]
add PAL_GREENBAR
ld [hli], a
inc hl
pop af
ld [hl], a
ld hl, wPalPacket
ld de, BlkPacket_StatusScreen
ret
SetPal_PartyMenu:
ld hl, PalPacket_PartyMenu
ld de, wPartyMenuBlkPacket
ret
SetPal_Pokedex:
ld hl, PalPacket_Pokedex
ld de, wPalPacket
ld bc, $10
call CopyData
ld a, [wCurPartySpecies]
call DeterminePaletteIDOutOfBattle
ld hl, wPalPacket + 3
ld [hl], a
ld hl, wPalPacket
ld de, BlkPacket_Pokedex
ret
SetPal_Slots:
ld hl, PalPacket_Slots
ld de, BlkPacket_Slots
ret
SetPal_TitleScreen:
ld hl, PalPacket_Titlescreen
ld de, BlkPacket_Titlescreen
ret
; used mostly for menus and the Oak intro
SetPal_Generic:
ld hl, PalPacket_Generic
ld de, BlkPacket_WholeScreen
ret
SetPal_NidorinoIntro:
ld hl, PalPacket_NidorinoIntro
ld de, BlkPacket_NidorinoIntro
ret
SetPal_GameFreakIntro:
ld hl, PalPacket_GameFreakIntro
ld de, BlkPacket_GameFreakIntro
ld a, SET_PAL_GENERIC
ld [wDefaultPaletteCommand], a
ret
; uses PalPacket_Empty to build a packet based on the current map
SetPal_Overworld:
ld hl, PalPacket_Empty
ld de, wPalPacket
ld bc, $10
call CopyData
ld a, [wCurMapTileset]
cp CEMETERY
jr z, .PokemonTowerOrAgatha
cp CAVERN
jr z, .caveOrBruno
ld a, [wCurMap]
cp FIRST_INDOOR_MAP
jr c, .townOrRoute
cp CERULEAN_CAVE_2F
jr c, .normalDungeonOrBuilding
cp CERULEAN_CAVE_1F + 1
jr c, .caveOrBruno
cp LORELEIS_ROOM
jr z, .Lorelei
cp BRUNOS_ROOM
jr z, .caveOrBruno
.normalDungeonOrBuilding
ld a, [wLastMap] ; town or route that current dungeon or building is located
.townOrRoute
cp NUM_CITY_MAPS
jr c, .town
ld a, PAL_ROUTE - 1
.town
inc a ; a town's palette ID is its map ID + 1
ld hl, wPalPacket + 1
ld [hld], a
ld de, BlkPacket_WholeScreen
ld a, SET_PAL_OVERWORLD
ld [wDefaultPaletteCommand], a
ret
.PokemonTowerOrAgatha
ld a, PAL_GRAYMON - 1
jr .town
.caveOrBruno
ld a, PAL_CAVE - 1
jr .town
.Lorelei
xor a
jr .town
; used when a Pokemon is the only thing on the screen
; such as evolution, trading and the Hall of Fame
SetPal_PokemonWholeScreen:
push bc
ld hl, PalPacket_Empty
ld de, wPalPacket
ld bc, $10
call CopyData
pop bc
ld a, c
and a
ld a, PAL_BLACK
jr nz, .next
ld a, [wWholeScreenPaletteMonSpecies]
call DeterminePaletteIDOutOfBattle
.next
ld [wPalPacket + 1], a
ld hl, wPalPacket
ld de, BlkPacket_WholeScreen
ret
SetPal_TrainerCard:
ld hl, BlkPacket_TrainerCard
ld de, wTrainerCardBlkPacket
ld bc, $40
call CopyData
ld de, BadgeBlkDataLengths
ld hl, wTrainerCardBlkPacket + 2
ld a, [wObtainedBadges]
ld c, NUM_BADGES
.badgeLoop
srl a
push af
jr c, .haveBadge
; The player doesn't have the badge, so zero the badge's blk data.
push bc
ld a, [de]
ld c, a
xor a
.zeroBadgeDataLoop
ld [hli], a
dec c
jr nz, .zeroBadgeDataLoop
pop bc
jr .nextBadge
.haveBadge
; The player does have the badge, so skip past the badge's blk data.
ld a, [de]
.skipBadgeDataLoop
inc hl
dec a
jr nz, .skipBadgeDataLoop
.nextBadge
pop af
inc de
dec c
jr nz, .badgeLoop
ld hl, PalPacket_TrainerCard
ld de, wTrainerCardBlkPacket
ret
SetPalFunctions:
; entries correspond to SET_PAL_* constants
dw SetPal_BattleBlack
dw SetPal_Battle
dw SetPal_TownMap
dw SetPal_StatusScreen
dw SetPal_Pokedex
dw SetPal_Slots
dw SetPal_TitleScreen
dw SetPal_NidorinoIntro
dw SetPal_Generic
dw SetPal_Overworld
dw SetPal_PartyMenu
dw SetPal_PokemonWholeScreen
dw SetPal_GameFreakIntro
dw SetPal_TrainerCard
; The length of the blk data of each badge on the Trainer Card.
; The Rainbow Badge has 3 entries because of its many colors.
BadgeBlkDataLengths:
db 6 ; Boulder Badge
db 6 ; Cascade Badge
db 6 ; Thunder Badge
db 6 * 3 ; Rainbow Badge
db 6 ; Soul Badge
db 6 ; Marsh Badge
db 6 ; Volcano Badge
db 6 ; Earth Badge
DeterminePaletteID:
bit TRANSFORMED, a ; a is battle status 3
ld a, PAL_GRAYMON ; if the mon has used Transform, use Ditto's palette
ret nz
ld a, [hl]
DeterminePaletteIDOutOfBattle:
ld [wPokedexNum], a
and a ; is the mon index 0?
jr z, .skipDexNumConversion
push bc
predef IndexToPokedex
pop bc
ld a, [wPokedexNum]
.skipDexNumConversion
ld e, a
ld d, 0
ld hl, MonsterPalettes ; not just for Pokemon, Trainers use it too
add hl, de
ld a, [hl]
ret
InitPartyMenuBlkPacket:
ld hl, BlkPacket_PartyMenu
ld de, wPartyMenuBlkPacket
ld bc, $30
jp CopyData
UpdatePartyMenuBlkPacket:
; Update the blk packet with the palette of the HP bar that is
; specified in [wWhichPartyMenuHPBar].
ld hl, wPartyMenuHPBarColors
ld a, [wWhichPartyMenuHPBar]
ld e, a
ld d, 0
add hl, de
ld e, l
ld d, h
ld a, [de]
and a
ld e, (1 << 2) | 1 ; green
jr z, .next
dec a
ld e, (2 << 2) | 2 ; yellow
jr z, .next
ld e, (3 << 2) | 3 ; red
.next
push de
ld hl, wPartyMenuBlkPacket + 8 + 1
ld bc, 6
ld a, [wWhichPartyMenuHPBar]
call AddNTimes
pop de
ld [hl], e
ret
SendSGBPacket:
;check number of packets
ld a, [hl]
and $07
ret z
; store number of packets in B
ld b, a
.loop2
; save B for later use
push bc
; disable ReadJoypad to prevent it from interfering with sending the packet
ld a, 1
ldh [hDisableJoypadPolling], a
; send RESET signal (P14=LOW, P15=LOW)
xor a ; JOYP_SGB_START
ldh [rJOYP], a
; set P14=HIGH, P15=HIGH
ld a, JOYP_SGB_FINISH
ldh [rJOYP], a
;load length of packets (16 bytes)
ld b, 16
.nextByte
;set bit counter (8 bits per byte)
ld e, 8
; get next byte in the packet
ld a, [hli]
ld d, a
.nextBit0
bit 0, d
; if 0th bit is not zero set P14=HIGH, P15=LOW (send bit 1)
ld a, JOYP_SGB_ONE
jr nz, .next0
; else (if 0th bit is zero) set P14=LOW, P15=HIGH (send bit 0)
ld a, JOYP_SGB_ZERO
.next0
ldh [rJOYP], a
; must set P14=HIGH,P15=HIGH between each "pulse"
ld a, JOYP_SGB_FINISH
ldh [rJOYP], a
; rotation will put next bit in 0th position (so we can always use command
; "bit 0, d" to fetch the bit that has to be sent)
rr d
; decrease bit counter so we know when we have sent all 8 bits of current byte
dec e
jr nz, .nextBit0
dec b
jr nz, .nextByte
; send bit 0 as a "stop bit" (end of parameter data)
ld a, JOYP_SGB_ZERO
ldh [rJOYP], a
; set P14=HIGH,P15=HIGH
ld a, JOYP_SGB_FINISH
ldh [rJOYP], a
xor a
ldh [hDisableJoypadPolling], a
; wait for about 70000 cycles
call Wait7000
; restore (previously pushed) number of packets
pop bc
dec b
; return if there are no more packets
ret z
; else send 16 more bytes
jr .loop2
LoadSGB:
xor a
ld [wOnSGB], a
call CheckSGB
ret nc
ld a, 1
ld [wOnSGB], a
ld a, [wOnCGB]
and a
jr z, .notCGB
ret
.notCGB
di
call PrepareSuperNintendoVRAMTransfer
ei
ld a, 1
ld [wCopyingSGBTileData], a
ld de, ChrTrnPacket
ld hl, SGBBorderGraphics
call CopyGfxToSuperNintendoVRAM
xor a
ld [wCopyingSGBTileData], a
ld de, PctTrnPacket
ld hl, BorderPalettes
call CopyGfxToSuperNintendoVRAM
xor a
ld [wCopyingSGBTileData], a
ld de, PalTrnPacket
ld hl, SuperPalettes
call CopyGfxToSuperNintendoVRAM
call ClearVram
ld hl, MaskEnCancelPacket
jp SendSGBPacket
PrepareSuperNintendoVRAMTransfer:
ld hl, .packetPointers
ld c, 9
.loop
push bc
ld a, [hli]
push hl
ld h, [hl]
ld l, a
call SendSGBPacket
pop hl
inc hl
pop bc
dec c
jr nz, .loop
ret
.packetPointers
; Only the first packet is needed.
dw MaskEnFreezePacket
dw DataSndPacket1
dw DataSndPacket2
dw DataSndPacket3
dw DataSndPacket4
dw DataSndPacket5
dw DataSndPacket6
dw DataSndPacket7
dw DataSndPacket8
CheckSGB:
; Returns whether the game is running on an SGB in carry.
ld hl, MltReq2Packet
di
call SendSGBPacket
ld a, 1
ldh [hDisableJoypadPolling], a
ei
call Wait7000
ldh a, [rJOYP]
and JOYP_SGB_MLT_REQ
cp JOYP_SGB_MLT_REQ
jr nz, .isSGB
ld a, JOYP_SGB_ZERO
ldh [rJOYP], a
ldh a, [rJOYP]
ldh a, [rJOYP]
call Wait7000
call Wait7000
ld a, JOYP_SGB_FINISH
ldh [rJOYP], a
call Wait7000
call Wait7000
ld a, JOYP_SGB_ONE
ldh [rJOYP], a
ldh a, [rJOYP]
ldh a, [rJOYP]
ldh a, [rJOYP]
ldh a, [rJOYP]
ldh a, [rJOYP]
ldh a, [rJOYP]
call Wait7000
vc_hook Unknown_network_reset
call Wait7000
ld a, JOYP_SGB_FINISH
ldh [rJOYP], a
ldh a, [rJOYP]
ldh a, [rJOYP]
ldh a, [rJOYP]
call Wait7000
call Wait7000
ldh a, [rJOYP]
and JOYP_SGB_MLT_REQ
cp JOYP_SGB_MLT_REQ
jr nz, .isSGB
call SendMltReq1Packet
and a
ret
.isSGB
call SendMltReq1Packet
scf
ret
SendMltReq1Packet:
ld hl, MltReq1Packet
call SendSGBPacket
jp Wait7000
CopyGfxToSuperNintendoVRAM:
di
push de
call DisableLCD
ld a, $e4
ldh [rBGP], a
ld de, vChars1
ld a, [wCopyingSGBTileData]
and a
jr z, .notCopyingTileData
call CopySGBBorderTiles
jr .next
.notCopyingTileData
ld bc, 256 tiles
call CopyData
.next
ld hl, vBGMap0
ld de, TILEMAP_WIDTH - SCREEN_WIDTH
ld a, $80
ld c, (256 + SCREEN_WIDTH - 1) / SCREEN_WIDTH ; enough rows to fit 256 tiles
.loop
ld b, SCREEN_WIDTH
.innerLoop
ld [hli], a
inc a
dec b
jr nz, .innerLoop
add hl, de
dec c
jr nz, .loop
ld a, LCDC_DEFAULT
ldh [rLCDC], a
pop hl
call SendSGBPacket
xor a
ldh [rBGP], a
ei
ret
Wait7000:
; Each loop takes 9 cycles so this routine actually waits 63000 cycles.
ld de, 7000
.loop
nop
nop
nop
dec de
ld a, d
or e
jr nz, .loop
ret
SendSGBPackets:
ld a, [wOnCGB]
and a
jr z, .notCGB
push de
call InitCGBPalettes
pop hl
call EmptyFunc3
ret
.notCGB
push de
call SendSGBPacket
pop hl
jp SendSGBPacket
InitCGBPalettes:
ld a, $80 ; index 0 with auto-increment
ldh [rBGPI], a
inc hl
ld c, $20
.loop
ld a, [hli]
inc hl
add a
add a
add a
ld de, SuperPalettes
add e
jr nc, .noCarry
inc d
.noCarry
ld a, [de]
ldh [rBGPD], a
dec c
jr nz, .loop
ret
EmptyFunc3:
ret
CopySGBBorderTiles:
; SGB tile data is stored in a 4BPP planar format.
; Each tile is 32 bytes. The first 16 bytes contain bit planes 1 and 2, while
; the second 16 bytes contain bit planes 3 and 4.
; This function converts 2BPP planar data into this format by mapping
; 2BPP colors 0-3 to 4BPP colors 0-3. 4BPP colors 4-15 are not used.
ld b, 128
.tileLoop
; Copy bit planes 1 and 2 of the tile data.
ld c, TILE_SIZE
.copyLoop
ld a, [hli]
ld [de], a
inc de
dec c
jr nz, .copyLoop
; Zero bit planes 3 and 4.
ld c, 16
xor a
.zeroLoop
ld [de], a
inc de
dec c
jr nz, .zeroLoop
dec b
jr nz, .tileLoop
ret
INCLUDE "data/sgb/sgb_packets.asm"
INCLUDE "data/pokemon/palettes.asm"
INCLUDE "data/sgb/sgb_palettes.asm"
INCLUDE "data/sgb/sgb_border.asm"
; END_INCLUDE \\?\M:\Code\Research\pokered-master\engine\gfx\palettes.asm
; BEGIN_INCLUDE \\?\M:\Code\Research\pokered-master\engine\menus\save.asm
TryLoadSaveFile:
call ClearScreen
call LoadFontTilePatterns
call LoadTextBoxTilePatterns
call LoadMainData
jr c, .badsum
call LoadCurrentBoxData
jr c, .badsum
call LoadPartyAndDexData
jr c, .badsum
ld a, $2 ; good checksum
jr .done
.badsum
ld hl, wStatusFlags5
push hl
set BIT_NO_TEXT_DELAY, [hl]
ld hl, FileDataDestroyedText
call PrintText
ld c, 100
call DelayFrames
pop hl
res BIT_NO_TEXT_DELAY, [hl]
ld a, $1 ; bad checksum
.done
ld [wSaveFileStatus], a
ret
FileDataDestroyedText:
text_far _FileDataDestroyedText
text_end
LoadMainData:
ld a, RAMG_SRAM_ENABLE
ld [rRAMG], a
ld a, BMODE_ADVANCED
ld [rBMODE], a
ASSERT BANK("Save Data") == BMODE_ADVANCED
ld [rRAMB], a
; This vc_hook does not have to be in any particular location.
; It is defined here because it refers to the same labels as the two lines below.
vc_hook Unknown_save_limit
ld hl, sGameData
ld bc, sGameDataEnd - sGameData
call CalcCheckSum
ld c, a
ld a, [sMainDataCheckSum]
cp c
jp z, .checkSumMatched
; If the computed checksum didn't match the saved on, try again.
ld hl, sGameData
ld bc, sGameDataEnd - sGameData
call CalcCheckSum
ld c, a
ld a, [sMainDataCheckSum]
cp c
jp nz, CheckSumFailed
.checkSumMatched
ld hl, sPlayerName
ld de, wPlayerName
ld bc, NAME_LENGTH
call CopyData
ld hl, sMainData
ld de, wMainDataStart
ld bc, wMainDataEnd - wMainDataStart
call CopyData
ld hl, wCurMapTileset
set BIT_NO_PREVIOUS_MAP, [hl]
ld hl, sSpriteData
ld de, wSpriteDataStart
ld bc, wSpriteDataEnd - wSpriteDataStart
call CopyData
ld a, [sTileAnimations]
ldh [hTileAnimations], a
; this part is redundant, LoadCurrentBoxData is always called next
ld hl, sCurBoxData
ld de, wBoxDataStart
ld bc, wBoxDataEnd - wBoxDataStart
call CopyData
and a
jp GoodCheckSum
LoadCurrentBoxData:
ld a, RAMG_SRAM_ENABLE
ld [rRAMG], a
ld a, BMODE_ADVANCED
ld [rBMODE], a
ASSERT BANK("Save Data") == BMODE_ADVANCED
ld [rRAMB], a
ld hl, sGameData
ld bc, sGameDataEnd - sGameData
call CalcCheckSum
ld c, a
ld a, [sMainDataCheckSum]
cp c
jr nz, CheckSumFailed
ld hl, sCurBoxData
ld de, wBoxDataStart
ld bc, wBoxDataEnd - wBoxDataStart
call CopyData
and a
jp GoodCheckSum
LoadPartyAndDexData:
ld a, RAMG_SRAM_ENABLE
ld [rRAMG], a
ld a, BMODE_ADVANCED
ld [rBMODE], a
ASSERT BANK("Save Data") == BMODE_ADVANCED
ld [rRAMB], a
ld hl, sGameData
ld bc, sGameDataEnd - sGameData
call CalcCheckSum
ld c, a
ld a, [sMainDataCheckSum]
cp c
jp nz, CheckSumFailed
ld hl, sPartyData
ld de, wPartyDataStart
ld bc, wPartyDataEnd - wPartyDataStart
call CopyData
ld hl, sMainData
ld de, wPokedexOwned
ld bc, wPokedexSeenEnd - wPokedexOwned
call CopyData
and a
jp GoodCheckSum
CheckSumFailed:
scf
; fallthrough
GoodCheckSum:
ld a, BMODE_SIMPLE ; preserve flags
ld [rBMODE], a
ASSERT RAMG_SRAM_DISABLE == BMODE_SIMPLE
ld [rRAMG], a
ret
TryLoadSaveFileIgnoreChecksum: ; unreferenced
; don't update wSaveFileStatus upon success or failure
; don't display warning in case of failed checksum
call LoadMainData
call LoadCurrentBoxData
jp LoadPartyAndDexData
SaveMenu:
farcall PrintSaveScreenText
ld hl, WouldYouLikeToSaveText
call SaveTheGame_YesOrNo
and a ;|0 = Yes|1 = No|
ret nz
ld a, [wSaveFileStatus]
dec a
jr z, .save
call CheckPreviousSaveFile
jr z, .save
ld hl, OlderFileWillBeErasedText
call SaveTheGame_YesOrNo
and a
ret nz
.save
call SaveGameData
hlcoord 1, 13
lb bc, 4, 18
call ClearScreenArea
hlcoord 1, 14
ld de, NowSavingString
call PlaceString
ld c, 120
call DelayFrames
ld hl, GameSavedText
call PrintText
ld a, SFX_SAVE
call PlaySoundWaitForCurrent
call WaitForSoundToFinish
ld c, 30
jp DelayFrames
NowSavingString:
db "Now saving...@"
SaveTheGame_YesOrNo:
call PrintText
hlcoord 0, 7
lb bc, 8, 1
ld a, TWO_OPTION_MENU
ld [wTextBoxID], a
call DisplayTextBoxID
ld a, [wCurrentMenuItem]
ret
WouldYouLikeToSaveText:
text_far _WouldYouLikeToSaveText
text_end
GameSavedText:
text_far _GameSavedText
text_end
OlderFileWillBeErasedText:
text_far _OlderFileWillBeErasedText
text_end
SaveMainData:
ld a, RAMG_SRAM_ENABLE
ld [rRAMG], a
ld a, BMODE_ADVANCED
ld [rBMODE], a
ASSERT BANK("Save Data") == BMODE_ADVANCED
ld [rRAMB], a
ld hl, wPlayerName
ld de, sPlayerName
ld bc, NAME_LENGTH
call CopyData
ld hl, wMainDataStart
ld de, sMainData
ld bc, wMainDataEnd - wMainDataStart
call CopyData
ld hl, wSpriteDataStart
ld de, sSpriteData
ld bc, wSpriteDataEnd - wSpriteDataStart
call CopyData
; this part is redundant, SaveCurrentBoxData is always called next
ld hl, wBoxDataStart
ld de, sCurBoxData
ld bc, wBoxDataEnd - wBoxDataStart
call CopyData
ldh a, [hTileAnimations]
ld [sTileAnimations], a
ld hl, sGameData
ld bc, sGameDataEnd - sGameData
call CalcCheckSum
ld [sMainDataCheckSum], a
xor a
ld [rBMODE], a
ld [rRAMG], a
ret
SaveCurrentBoxData:
ld a, RAMG_SRAM_ENABLE
ld [rRAMG], a
ld a, BMODE_ADVANCED
ld [rBMODE], a
ASSERT BANK("Save Data") == BMODE_ADVANCED
ld [rRAMB], a
ld hl, wBoxDataStart
ld de, sCurBoxData
ld bc, wBoxDataEnd - wBoxDataStart
call CopyData
ld hl, sGameData
ld bc, sGameDataEnd - sGameData
call CalcCheckSum
ld [sMainDataCheckSum], a
xor a
ld [rBMODE], a
ld [rRAMG], a
ret
SavePartyAndDexData:
ld a, RAMG_SRAM_ENABLE
ld [rRAMG], a
ld a, BMODE_ADVANCED
ld [rBMODE], a
ASSERT BANK("Save Data") == BMODE_ADVANCED
ld [rRAMB], a
ld hl, wPartyDataStart
ld de, sPartyData
ld bc, wPartyDataEnd - wPartyDataStart
call CopyData
ld hl, wPokedexOwned ; pok dex only
ld de, sMainData
ld bc, wPokedexSeenEnd - wPokedexOwned
call CopyData
ld hl, sGameData
ld bc, sGameDataEnd - sGameData
call CalcCheckSum
ld [sMainDataCheckSum], a
xor a
ld [rBMODE], a
ld [rRAMG], a
ret
SaveGameData::
ld a, $2
ld [wSaveFileStatus], a
call SaveMainData
call SaveCurrentBoxData
jp SavePartyAndDexData
CalcCheckSum:
;Check Sum (result[1 byte] is complemented)
ld d, 0
.loop
ld a, [hli]
add d
ld d, a
dec bc
ld a, b
or c
jr nz, .loop
ld a, d
cpl
ret
CalcIndividualBoxCheckSums:
ld hl, sBox1 ; sBox7
ld de, sBank2IndividualBoxChecksums ; sBank3IndividualBoxChecksums
ld b, NUM_BOXES / 2
.loop
push bc
push de
ld bc, wBoxDataEnd - wBoxDataStart
call CalcCheckSum
pop de
ld [de], a
inc de
pop bc
dec b
jr nz, .loop
ret
GetBoxSRAMLocation:
; in: a = box num
; out: b = box SRAM bank, hl = pointer to start of box
ld hl, BoxSRAMPointerTable
ld a, [wCurrentBoxNum]
and BOX_NUM_MASK
cp NUM_BOXES / 2
ld b, 2
jr c, .next
inc b
sub NUM_BOXES / 2
.next
ld e, a
ld d, 0
add hl, de
add hl, de
ld a, [hli]
ld h, [hl]
ld l, a
ret
BoxSRAMPointerTable:
dw sBox1 ; sBox7
dw sBox2 ; sBox8
dw sBox3 ; sBox9
dw sBox4 ; sBox10
dw sBox5 ; sBox11
dw sBox6 ; sBox12
ChangeBox::
ld hl, WhenYouChangeBoxText
call PrintText
call YesNoChoice
ld a, [wCurrentMenuItem]
and a
ret nz ; return if No was chosen
ld hl, wCurrentBoxNum
bit BIT_HAS_CHANGED_BOXES, [hl] ; is it the first time player is changing the box?
call z, EmptyAllSRAMBoxes ; if so, empty all boxes in SRAM
call DisplayChangeBoxMenu
call UpdateSprites
ld hl, hUILayoutFlags
set BIT_DOUBLE_SPACED_MENU, [hl]
call HandleMenuInput
ld hl, hUILayoutFlags
res BIT_DOUBLE_SPACED_MENU, [hl]
bit B_PAD_B, a
ret nz
call GetBoxSRAMLocation
ld e, l
ld d, h
ld hl, wBoxDataStart
call CopyBoxToOrFromSRAM ; copy old box from WRAM to SRAM
ld a, [wCurrentMenuItem]
set BIT_HAS_CHANGED_BOXES, a
ld [wCurrentBoxNum], a
call GetBoxSRAMLocation
ld de, wBoxDataStart
call CopyBoxToOrFromSRAM ; copy new box from SRAM to WRAM
ld hl, wCurMapTextPtr
ld de, wChangeBoxSavedMapTextPointer
ld a, [hli]
ld [de], a
inc de
ld a, [hl]
ld [de], a
call RestoreMapTextPointer
call SaveGameData
ld hl, wChangeBoxSavedMapTextPointer
call SetMapTextPointer
ld a, SFX_SAVE
call PlaySoundWaitForCurrent
call WaitForSoundToFinish
ret
WhenYouChangeBoxText:
text_far _WhenYouChangeBoxText
text_end
CopyBoxToOrFromSRAM:
; copy an entire box from hl to de with b as the SRAM bank
push hl
ld a, RAMG_SRAM_ENABLE
ld [rRAMG], a
ld a, BMODE_ADVANCED
ld [rBMODE], a
ld a, b
ld [rRAMB], a
ld bc, wBoxDataEnd - wBoxDataStart
call CopyData
pop hl
; mark the source box as an empty box
xor a
ld [hli], a
dec a
ld [hl], a
ld hl, sBox1 ; sBox7
ld bc, sBank2AllBoxesChecksum - sBox1
call CalcCheckSum
ld [sBank2AllBoxesChecksum], a ; sBank3AllBoxesChecksum
call CalcIndividualBoxCheckSums
xor a
ld [rBMODE], a
ld [rRAMG], a
ret
DisplayChangeBoxMenu:
xor a
ldh [hAutoBGTransferEnabled], a
ld a, PAD_A | PAD_B
ld [wMenuWatchedKeys], a
ld a, 11
ld [wMaxMenuItem], a
ld a, 1
ld [wTopMenuItemY], a
ld a, 12
ld [wTopMenuItemX], a
xor a
ld [wMenuWatchMovingOutOfBounds], a
ld a, [wCurrentBoxNum]
and BOX_NUM_MASK
ld [wCurrentMenuItem], a
ld [wLastMenuItem], a
hlcoord 0, 0
ld b, 2
ld c, 9
call TextBoxBorder
ld hl, ChooseABoxText
call PrintText
hlcoord 11, 0
ld b, 12
ld c, 7
call TextBoxBorder
ld hl, hUILayoutFlags
set BIT_SINGLE_SPACED_LINES, [hl]
ld de, BoxNames
hlcoord 13, 1
call PlaceString
ld hl, hUILayoutFlags
res BIT_SINGLE_SPACED_LINES, [hl]
ld a, [wCurrentBoxNum]
and BOX_NUM_MASK
cp 9
jr c, .singleDigitBoxNum
sub 9
hlcoord 8, 2
ld [hl], '1'
add '0'
jr .next
.singleDigitBoxNum
add '1'
.next
ldcoord_a 9, 2
hlcoord 1, 2
ld de, BoxNoText
call PlaceString
call GetMonCountsForAllBoxes
hlcoord 18, 1
ld de, wBoxMonCounts
ld bc, SCREEN_WIDTH
ld a, NUM_BOXES
.loop
push af
ld a, [de]
and a ; is the box empty?
jr z, .skipPlacingPokeball
ld [hl], $78 ; place pokeball tile next to box name if box not empty
.skipPlacingPokeball
add hl, bc
inc de
pop af
dec a
jr nz, .loop
ld a, 1
ldh [hAutoBGTransferEnabled], a
ret
ChooseABoxText:
text_far _ChooseABoxText
text_end
BoxNames:
db "BOX 1"
next "BOX 2"
next "BOX 3"
next "BOX 4"
next "BOX 5"
next "BOX 6"
next "BOX 7"
next "BOX 8"
next "BOX 9"
next "BOX10"
next "BOX11"
next "BOX12@"
BoxNoText:
db "BOX No.@"
EmptyAllSRAMBoxes:
; marks all boxes in SRAM as empty (initialisation for the first time the
; player changes the box)
ld a, RAMG_SRAM_ENABLE
ld [rRAMG], a
ld a, BMODE_ADVANCED
ld [rBMODE], a
ld a, BANK("Saved Boxes 1")
ld [rRAMB], a
call EmptySRAMBoxesInBank
ld a, BANK("Saved Boxes 2")
ld [rRAMB], a
call EmptySRAMBoxesInBank
xor a
ld [rBMODE], a
ld [rRAMG], a
ret
EmptySRAMBoxesInBank:
; marks every box in the current SRAM bank as empty
ld hl, sBox1 ; sBox7
call EmptySRAMBox
ld hl, sBox2 ; sBox8
call EmptySRAMBox
ld hl, sBox3 ; sBox9
call EmptySRAMBox
ld hl, sBox4 ; sBox10
call EmptySRAMBox
ld hl, sBox5 ; sBox11
call EmptySRAMBox
ld hl, sBox6 ; sBox12
call EmptySRAMBox
ld hl, sBox1 ; sBox7
ld bc, sBank2AllBoxesChecksum - sBox1
call CalcCheckSum
ld [sBank2AllBoxesChecksum], a ; sBank3AllBoxesChecksum
call CalcIndividualBoxCheckSums
ret
EmptySRAMBox:
xor a
ld [hli], a
dec a
ld [hl], a
ret
GetMonCountsForAllBoxes:
ld hl, wBoxMonCounts
push hl
ld a, RAMG_SRAM_ENABLE
ld [rRAMG], a
ld a, BMODE_ADVANCED
ld [rBMODE], a
ld a, BANK("Saved Boxes 1")
ld [rRAMB], a
call GetMonCountsForBoxesInBank
ld a, BANK("Saved Boxes 2")
ld [rRAMB], a
call GetMonCountsForBoxesInBank
xor a
ld [rBMODE], a
ld [rRAMG], a
pop hl
; copy the count for the current box from WRAM
ld a, [wCurrentBoxNum]
and BOX_NUM_MASK
ld c, a
ld b, 0
add hl, bc
ld a, [wBoxCount]
ld [hl], a
ret
GetMonCountsForBoxesInBank:
ld a, [sBox1] ; sBox7
ld [hli], a
ld a, [sBox2] ; sBox8
ld [hli], a
ld a, [sBox3] ; sBox9
ld [hli], a
ld a, [sBox4] ; sBox10
ld [hli], a
ld a, [sBox5] ; sBox11
ld [hli], a
ld a, [sBox6] ; sBox12
ld [hli], a
ret
; check if we're trying to save over a different playthrough
; return result in zero flag
; z set: a valid save file was found, and saved PlayerID is different from wPlayerID
CheckPreviousSaveFile:
ld a, RAMG_SRAM_ENABLE
ld [rRAMG], a
ld a, BMODE_ADVANCED
ld [rBMODE], a
ASSERT BANK("Save Data") == BMODE_ADVANCED
ld [rRAMB], a
ld a, [sPlayerName]
and a
jr z, .next
ld hl, sGameData
ld bc, sGameDataEnd - sGameData
call CalcCheckSum
ld c, a
ld a, [sMainDataCheckSum]
cp c
jr nz, .next ; return z set if save data is corrupted
ld hl, sMainData + (wPlayerID - wMainDataStart) ; player ID
ld a, [hli]
ld h, [hl]
ld l, a
ld a, [wPlayerID]
cp l
jr nz, .next
ld a, [wPlayerID + 1]
cp h
.next
ld a, BMODE_SIMPLE
ld [rBMODE], a
ASSERT RAMG_SRAM_DISABLE == BMODE_SIMPLE
ld [rRAMG], a
ret
SaveHallOfFameTeams:
ld a, [wNumHoFTeams]
dec a
cp HOF_TEAM_CAPACITY
jr nc, .shiftHOFTeams
ld hl, sHallOfFame
ld bc, HOF_TEAM
call AddNTimes
ld e, l
ld d, h
ld hl, wHallOfFame
ld bc, HOF_TEAM
jr HallOfFame_Copy
.shiftHOFTeams
; if the space designated for HOF teams is full, then shift all HOF teams to the next slot, making space for the new HOF team
; this deletes the last HOF team though
ld hl, sHallOfFame + HOF_TEAM
ld de, sHallOfFame
ld bc, HOF_TEAM * (HOF_TEAM_CAPACITY - 1)
call HallOfFame_Copy
ld hl, wHallOfFame
ld de, sHallOfFame + HOF_TEAM * (HOF_TEAM_CAPACITY - 1)
ld bc, HOF_TEAM
jr HallOfFame_Copy
LoadHallOfFameTeams:
ld hl, sHallOfFame
ld bc, HOF_TEAM
ld a, [wHoFTeamIndex]
call AddNTimes
ld de, wHallOfFame
ld bc, HOF_TEAM
; fallthrough
HallOfFame_Copy:
ld a, RAMG_SRAM_ENABLE
ld [rRAMG], a
ld a, BMODE_ADVANCED
ld [rBMODE], a
xor a
ld [rRAMB], a
call CopyData
xor a
ld [rBMODE], a
ld [rRAMG], a
ret
; Fill SRAM with $ff, erasing save data. Used by DoClearSaveDialogue
ClearAllSRAMBanks:
ld a, RAMG_SRAM_ENABLE
ld [rRAMG], a
ld a, BMODE_ADVANCED
ld [rBMODE], a
xor a
call .PadSRAM_FF
ld a, 1
call .PadSRAM_FF
ld a, 2
call .PadSRAM_FF
ld a, 3
call .PadSRAM_FF
xor a
ld [rBMODE], a
ld [rRAMG], a
ret
.PadSRAM_FF
ld [rRAMB], a
ld hl, STARTOF(SRAM)
ld bc, SIZEOF(SRAM)
ld a, $ff
jp FillMemory
; END_INCLUDE \\?\M:\Code\Research\pokered-master\engine\menus\save.asm
SECTION "Itemfinder 1", ROMX
; BEGIN_INCLUDE \\?\M:\Code\Research\pokered-master\engine\movie\credits.asm
HallOfFamePC:
farcall AnimateHallOfFame
call ClearScreen
ld c, 100
call DelayFrames
call DisableLCD
ld hl, vFont
ld bc, ($80 tiles) / 2
call ShiftFontColorIndex
ld hl, vChars2 tile $60
ld bc, ($20 tiles) / 2
call ShiftFontColorIndex
ld hl, vChars2 tile $7e
ld bc, TILE_SIZE
ld a, $ff ; solid black
call FillMemory
hlcoord 0, 0
call FillFourRowsWithBlack
hlcoord 0, 14
call FillFourRowsWithBlack
ld a, %11000000
ldh [rBGP], a
call EnableLCD
ld a, SFX_STOP_ALL_MUSIC
call PlaySoundWaitForCurrent
ld c, BANK(Music_Credits)
ld a, MUSIC_CREDITS
call PlayMusic
ld c, 128
call DelayFrames
xor a
ld [wUnusedCreditsByte], a ; not read
ld [wNumCreditsMonsDisplayed], a
jp Credits
FadeInCredits:
ld hl, HoFGBPalettes
ld b, 4
.loop
ld a, [hli]
ldh [rBGP], a
ld c, 5
call DelayFrames
dec b
jr nz, .loop
ret
DisplayCreditsMon:
xor a
ldh [hAutoBGTransferEnabled], a
call SaveScreenTilesToBuffer1
call FillMiddleOfScreenWithWhite
; display the next monster from CreditsMons
ld hl, wNumCreditsMonsDisplayed
ld c, [hl] ; how many monsters have we displayed so far?
inc [hl]
ld b, 0
ld hl, CreditsMons
add hl, bc ; go that far in the list of monsters and get the next one
ld a, [hl]
ld [wCurPartySpecies], a
ld [wCurSpecies], a
hlcoord 8, 6
call GetMonHeader
call LoadFrontSpriteByMonIndex
ld hl, vBGMap0 + $c
call CreditsCopyTileMapToVRAM
xor a
ldh [hAutoBGTransferEnabled], a
call LoadScreenTilesFromBuffer1
ld hl, vBGMap0
call CreditsCopyTileMapToVRAM
ld a, $A7
ldh [rWX], a
ld hl, vBGMap1
call CreditsCopyTileMapToVRAM
call FillMiddleOfScreenWithWhite
ld a, %11111100 ; make the mon a black silhouette
ldh [rBGP], a
; scroll the mon left by one tile 7 times
ld bc, 7
.scrollLoop1
call ScrollCreditsMonLeft
dec c
jr nz, .scrollLoop1
; scroll the mon left by one tile 20 times
; This time, we have to move the window left too in order to hide the text that
; is wrapping around to the right side of the screen.
ld c, 20
.scrollLoop2
call ScrollCreditsMonLeft
ldh a, [rWX]
sub 8
ldh [rWX], a
dec c
jr nz, .scrollLoop2
xor a
ldh [hWY], a
ld a, %11000000
ldh [rBGP], a
ret
INCLUDE "data/credits/credits_mons.asm"
ScrollCreditsMonLeft:
ld h, b
ld l, $20
call ScrollCreditsMonLeft_SetSCX
ld h, $0
ld l, $70
call ScrollCreditsMonLeft_SetSCX
ld a, b
add $8
ld b, a
ret
ScrollCreditsMonLeft_SetSCX:
ldh a, [rLY]
cp l
jr nz, ScrollCreditsMonLeft_SetSCX
ld a, h
ldh [rSCX], a
.loop
ldh a, [rLY]
cp h
jr z, .loop
ret
HoFGBPalettes:
dc 3, 0, 0, 0
dc 3, 1, 0, 0
dc 3, 2, 0, 0
dc 3, 3, 0, 0
CreditsCopyTileMapToVRAM:
ld a, l
ldh [hAutoBGTransferDest], a
ld a, h
ldh [hAutoBGTransferDest + 1], a
ld a, 1
ldh [hAutoBGTransferEnabled], a
jp Delay3
ShiftFontColorIndex:
; Zero every second byte at hl, writing a total of bc bytes.
; When used on VRAM font characters that contain only black and white shades,
; it shifts the color index: black -> light gray, allowing palette-controlled
; text fade-in during the Credits roll, while the black bars remain solid.
ld [hl], 0
inc hl
inc hl
dec bc
ld a, b
or c
jr nz, ShiftFontColorIndex
ret
FillFourRowsWithBlack:
ld bc, SCREEN_WIDTH * 4
ld a, $7e
jp FillMemory
FillMiddleOfScreenWithWhite:
hlcoord 0, 4
ld bc, SCREEN_WIDTH * 10
ld a, ' '
jp FillMemory
Credits:
ld de, CreditsOrder
push de
.nextCreditsScreen
pop de
hlcoord 9, 6
push hl
call FillMiddleOfScreenWithWhite
pop hl
.nextCreditsCommand
ld a, [de]
inc de
push de
cp CRED_TEXT_FADE_MON
jr z, .fadeInTextAndShowMon
cp CRED_TEXT_MON
jr z, .showTextAndShowMon
cp CRED_TEXT_FADE
jr z, .fadeInText
cp CRED_TEXT
jr z, .showText
cp CRED_COPYRIGHT
jr z, .showCopyrightText
cp CRED_THE_END
jr z, .showTheEnd
push hl
push hl
ld hl, CreditsTextPointers
add a
ld c, a
ld b, 0
add hl, bc
ld e, [hl]
inc hl
ld d, [hl]
ld a, [de]
inc de
ld c, a
ld b, -1
pop hl
add hl, bc
call PlaceString
pop hl
ld bc, SCREEN_WIDTH * 2
add hl, bc
pop de
jr .nextCreditsCommand
.fadeInTextAndShowMon
call FadeInCredits
ld c, 90
jr .next1
.showTextAndShowMon
ld c, 110
.next1
call DelayFrames
call DisplayCreditsMon
jr .nextCreditsScreen
.fadeInText
call FadeInCredits
ld c, 120
jr .next2
.showText
ld c, 140
.next2
call DelayFrames
jr .nextCreditsScreen
.showCopyrightText
push de
farcall LoadCopyrightTiles
pop de
pop de
jr .nextCreditsCommand
.showTheEnd
ld c, 16
call DelayFrames
call FillMiddleOfScreenWithWhite
pop de
ld de, TheEndGfx
ld hl, vChars2 tile $60
lb bc, BANK(TheEndGfx), (TheEndGfxEnd - TheEndGfx) / TILE_SIZE
call CopyVideoData
hlcoord 4, 8
ld de, TheEndTextString
call PlaceString
hlcoord 4, 9
inc de
call PlaceString
jp FadeInCredits
TheEndTextString:
; "T H E E N D"
db $60," ",$62," ",$64," ",$64," ",$66," ",$68,"@"
db $61," ",$63," ",$65," ",$65," ",$67," ",$69,"@"
INCLUDE "data/credits/credits_order.asm"
INCLUDE "data/credits/credits_text.asm"
TheEndGfx:
INCBIN "gfx/credits/the_end.2bpp"
TheEndGfxEnd:
; END_INCLUDE \\?\M:\Code\Research\pokered-master\engine\movie\credits.asm
; BEGIN_INCLUDE \\?\M:\Code\Research\pokered-master\engine\pokemon\status_ailments.asm
PrintStatusAilment::
ld a, [de]
bit PSN, a
jr nz, .psn
bit BRN, a
jr nz, .brn
bit FRZ, a
jr nz, .frz
bit PAR, a
jr nz, .par
and SLP_MASK
ret z
ld_hli_a_string "SLP"
ret
.psn
ld_hli_a_string "PSN"
ret
.brn
ld_hli_a_string "BRN"
ret
.frz
ld_hli_a_string "FRZ"
ret
.par
ld_hli_a_string "PAR"
ret
; END_INCLUDE \\?\M:\Code\Research\pokered-master\engine\pokemon\status_ailments.asm
; BEGIN_INCLUDE \\?\M:\Code\Research\pokered-master\engine\items\itemfinder.asm
HiddenItemNear:
ld hl, HiddenItemCoords
ld b, 0
.loop
ld de, 3
ld a, [wCurMap]
call IsInRestOfArray
ret nc ; return if current map has no hidden items
push bc
push hl
ld hl, wObtainedHiddenItemsFlags
ld c, b
ld b, FLAG_TEST
predef FlagActionPredef
ld a, c
pop hl
pop bc
inc b
and a
inc hl
ld d, [hl]
inc hl
ld e, [hl]
inc hl
jr nz, .loop ; if the item has already been obtained
; check if the item is within 4-5 tiles (depending on the direction of item)
ld a, [wYCoord]
call Sub5ClampTo0
cp d
jr nc, .loop
ld a, [wYCoord]
add 4
cp d
jr c, .loop
ld a, [wXCoord]
call Sub5ClampTo0
cp e
jr nc, .loop
ld a, [wXCoord]
add 5
cp e
jr c, .loop
scf
ret
Sub5ClampTo0:
; subtract 5 but clamp to 0
sub 5
cp $f0
ret c
xor a
ret
; END_INCLUDE \\?\M:\Code\Research\pokered-master\engine\items\itemfinder.asm
SECTION "Vending Machine", ROMX
; BEGIN_INCLUDE \\?\M:\Code\Research\pokered-master\engine\events\vending_machine.asm
VendingMachineMenu::
ld hl, VendingMachineText1
call PrintText
ld a, MONEY_BOX
ld [wTextBoxID], a
call DisplayTextBoxID
xor a
ld [wCurrentMenuItem], a
ld [wLastMenuItem], a
ld a, PAD_A | PAD_B
ld [wMenuWatchedKeys], a
ld a, 3
ld [wMaxMenuItem], a
ld a, 5
ld [wTopMenuItemY], a
ld a, 1
ld [wTopMenuItemX], a
ld hl, wStatusFlags5
set BIT_NO_TEXT_DELAY, [hl]
hlcoord 0, 3
ld b, 8
ld c, 12
call TextBoxBorder
call UpdateSprites
hlcoord 2, 5
ld de, DrinkText
call PlaceString
hlcoord 9, 6
ld de, DrinkPriceText
call PlaceString
ld hl, wStatusFlags5
res BIT_NO_TEXT_DELAY, [hl]
call HandleMenuInput
bit B_PAD_B, a
jr nz, .notThirsty
ld a, [wCurrentMenuItem]
cp 3 ; chose Cancel?
jr z, .notThirsty
xor a
ldh [hMoney], a
ldh [hMoney + 2], a
ld a, $2
ldh [hMoney + 1], a
call HasEnoughMoney
jr nc, .enoughMoney
ld hl, VendingMachineText4
jp PrintText
.enoughMoney
call LoadVendingMachineItem
