ldh [hCoins + 1], a
jr .bcdDone
.bcd100
ld a, $1
ldh [hCoins], a
.bcdDone
ld de, wPlayerCoins + 1
ld hl, hCoins + 1
ld c, $2
predef AddBCDPredef
